// ---------- 商店 · 设置：英语、法语界面和非默认字体要先用金币买 ----------
// 购买记成 game 记录（kind "buy"）；永久拥有、跟着账号同步，关闭游戏模式也保留购买门槛。
const SET_ITEMS = [
  { id: "lang-fr", lang: "fr", name: "法语界面", desc: "界面和解析都换成法语，法语模式下答对得到的金币 ×3", price: 10000, prev: "FR" },
  { id: "lang-en", lang: "en", name: "英文界面", desc: "界面、题目解析、知识点卡片、巴黎塔尖事件和 Boss 题都换成英文；英文模式下答对得到的金币翻倍。", price: 1000, prev: "EN" },
  { id: "font-times", name: "字体 · Times New Roman", desc: "英文和法语字母用 Times New Roman。", price: 200, prev: "Aa", font: "times" },
  { id: "font-kreon", name: "字体 · Kreon", desc: "英文和法语字母用 Kreon。", price: 200, prev: "Aa", font: "kreon" },
];
const setOwned = id => typeof gameLedger !== "function" || gameLedger().owned.has(id);
// 答题记录读到后检查：没买的语言 / 字体换回默认
function setGate() {
  if (!gameLoaded) return;
  if (UI_FONT !== "default" && !setOwned("font-" + UI_FONT)) setUiFont("default");
  if ((UI_LANG === "zh" || setOwned("lang-" + UI_LANG)) && langAt(Date.now()) !== UI_LANG) { gameAdd({ kind: "lang", lang: UI_LANG, at: new Date().toISOString() }); prog = null; }   // 从此刻起采用当前语言的倍数，不改变旧答题记录
  // 按存下的选择判断（语言包没下载成功时 UI_LANG 已经是中文，但选择还在）
  const want = (() => { try { return localStorage.getItem("fq-lang"); } catch (e) { return null; } })();
  if (["en", "fr"].includes(want) && !setOwned("lang-" + want)) {
    langMark("zh"); prog = null;
    try { localStorage.setItem("fq-lang", "zh"); } catch (e) {}
    if (UI_LANG !== "zh") {
      if (typeof xpToast === "function") xpToast(tr("所选界面语言要先在“商店 · 设置”里解锁"), tr("已换回中文"));
      setTimeout(() => location.reload(), 1800);
    }
  }
}
function setBuy(id) {
  const it = SET_ITEMS.find(x => x.id === id), led = gameLedger();
  if (led.owned.has(id)) return "已经拥有";
  if (led.coins < it.price) return "金币不够";
  gameAdd({ kind: "buy", item: id, price: it.price, at: new Date().toISOString() });
  return "";
}
function setShop(note) {
  const led = gameLedger(), ownN = SET_ITEMS.filter(x => led.owned.has(x.id)).length;
  const wrap = foldSec("setshop", "商店 · 设置", `界面语言、字体 · 已拥有 ${ownN} / ${SET_ITEMS.length}`);
  wrap.classList.add("cos-shop");
  const grid = el("div", "cos-grid");
  SET_ITEMS.forEach(it => {
    const own = led.owned.has(it.id), on = it.font ? UI_FONT === it.font : UI_LANG === it.lang;
    const card = el("div", "cos-item" + (on ? " on" : ""));
    const pv = el("div", "set-prev" + (it.font ? " f-" + it.font : ""), it.prev);
    card.append(pv, el("b", null, it.name), el("span", "cos-desc", it.desc));
    const btn = el("button", own && !on ? "btn" : "btn ghost"); btn.type = "button"; btn.id = "set-" + it.id;
    if (!own) {
      btn.append(document.createTextNode("购买 "), coinEl(it.price));
      btn.disabled = led.coins < it.price;
      let sure = false;
      btn.addEventListener("click", () => {
        if (!sure) { sure = true; btn.textContent = `确认花 ${it.price} 金币`; return; }
        const err = setBuy(it.id); if (err) { note.textContent = err; return; }
        xpToast(`花了 ${it.price} 金币`, `买到了：${it.name}`);
        shopRedraw();
      });
    } else {
      btn.textContent = on ? (it.font ? "换回默认" : "换回中文") : "使用";
      btn.addEventListener("click", () => {
        if (it.font) { setUiFont(on ? "default" : it.font); shopRedraw(); }
        else setUiLang(on ? "zh" : it.lang);
      });
    }
    card.append(btn); grid.append(card);
  });
  wrap.append(grid, el("p", "shop-note", "买一次永久拥有。也可以在“设置”页切换。"));
  return wrap;
}

// ---------- 答题记录存储（错题本、学习进度、经验值都从这里算） ----------
let dbRef = null;
const LOCAL = typeof claude === "undefined";   // 在 GitHub Pages 等普通网页里打开
// 记录存在这台设备的浏览器里，每种记录一个键
function localDb(ns) {
  const key = c => `${ns}-db-${c}`;
  const load = c => { try { return JSON.parse(localStorage.getItem(key(c)) || "[]"); } catch (e) { return []; } };
  const snap = arr => ({ size: arr.length, docs: arr.map(d => ({ data: () => d })) });
  return { collection: c => ({
    add: async d => { const a = load(c); a.push(d); localStorage.setItem(key(c), JSON.stringify(a)); if (typeof syncPush === "function") syncPush(c, d); },
    get: async () => snap(load(c)),
    where: (f, op, v) => ({ get: async () => snap(load(c).filter(d => d[f] === v)) }),
  }) };
}
(async () => {
  try {
    dbRef = LOCAL ? localDb("fq") : await claude.use("db");
    if (!dbRef) { saveNote.textContent = "当前视图无法保存记录，答题不受影响。"; return; }
    const docs = (await dbRef.collection("answers").get()).docs.map(d => d.data());
    let voc = [];
    try { voc = (await dbRef.collection("vocab").get()).docs.map(d => d.data()); } catch (e) {}
    try { gameReset((await dbRef.collection("game").get()).docs.map(d => d.data())); } catch (e) {}
    progReset(docs, voc); progEnsure(); planRefresh();
    if (typeof petOnDataReady === "function") petOnDataReady();
    if (typeof syncNow === "function") syncNow(true);   // 公开网站登录后：和云端同步
    const wrong = docs.filter(d => !d.isCorrect).length;
    saveNote.textContent = wrong ? `已有 ${wrong} 条错题记录，答题记录会自动保存到学习进度。` : "答题记录会自动保存到学习进度。";
    if (LOCAL) saveNote.textContent += "记录保存在这台设备的浏览器里，换设备或清除浏览器数据后不会保留。";
    if (view === "book") renderBook();
    if (view === "cafe" && typeof cafeEnter === "function") cafeEnter();
  } catch (e) { saveNote.textContent = "暂时无法读取答题记录，答题不受影响。"; }
})();
function record(item, i, right) {
  if (!dbRef) return;
  const d = {
    round: roundOf(item.id), qid: item.id, ch: item.ch, cat: item.cat, question: item.title ? `（长文听力 · ${item.title}）${item.q}` : item.audio ? "（听力）" + item.audio : item.q,
    chosen: item.opts[i], correct: item.opts[item.a], isCorrect: right, at: new Date().toISOString(),
  };
  dbRef.collection("answers").add(d).catch(() => { saveNote.textContent = "有一条记录没保存成功，答题不受影响。"; });
  progLive(d, "ans");
  bookCache = null;
}
// ---------- 状态 ----------
