  skip.addEventListener("click", endReview);
  const prev = el("button", "btn ghost", "上一条");
  prev.type = "button";
  prev.id = "kpPrev";
  prev.disabled = pos === 0;
  prev.addEventListener("click", () => { rv.pos--; renderReview(); });
  const n = bEnd() - idx;
  const next = el("button", "btn", last ? `开始答题（${n} 题）` : "下一条");
  next.type = "button";
  next.id = "kpNext";
  next.addEventListener("click", () => { if (last) endReview(); else { rv.pos++; renderReview(); } });
  actions.append(skip, prev, next);
