  const head = el("div", "xp-head");
  const badge = el("div", "xp-badge"); badge.append(el("small", null, "Lv"), el("b", null, String(L.lv)));
  const info = el("div", "xp-info");
  const title = el("div", "xp-title"); title.append(el("b", null, xpTitle(L.lv)), el("span", null, `今日 +${prog ? prog.today : 0} 经验`));
  const bar = el("div", "xp-bar"), fill = el("i"); fill.style.width = (L.cur / L.need * 100) + "%"; bar.append(fill);
  info.append(title, bar, el("div", "xp-num", `本级 ${L.cur} / ${L.need} · 总经验 ${prog ? prog.xp : 0} · 学习 ${prog ? prog.days : 0} 天`));
  head.append(badge, info);
