// 答完一题后：今天目标刚达成 / 今日计划刚做完时，返回一句大提示
function planNotice(d, todayBefore) {
  const p = planGet();
  if (p) {
    const ids = [...p.review, ...p.fresh, ...p.weak];
    const s = planStatus(p);
    const hit = d.round === "cj" ? hasConj() && conjToday() === PLAN_CONJ : ids.includes(d.qid);
    if (hit && s.n && s.d === s.n) return "今日计划完成！";
  }
  if (todayBefore < xpGoal && prog.today >= xpGoal) return `今日目标达成！连续 ${streakInfo().n} 天`;
  return "";
}

// 今日计划进度条：宽屏放在目录顶上，窄屏（目录收起时）放在主区域最上面；点了直接开始
function planTocItem(id = "planToc") {
  const box = el("button", "plan-toc"); box.type = "button"; box.id = id;
  const p = planGet();
  if (!p) { box.disabled = true; box.append(el("b", null, "今日计划"), el("span", null, "正在读取答题记录…")); return box; }
  const s = planStatus(p), st = streakInfo();
  const bar = el("span", "pbar"), fill = el("i", "mastery"); fill.style.width = (s.n ? s.d / s.n * 100 : 0) + "%"; bar.append(fill);
  const gm = typeof gameOn === "function" && gameOn();
  const pa = gm ? potionActive() : null;
  const coins = gm ? ` · ${gameLedger().coins} 金币` : "";
  const ca = gm && typeof coinPotionActive === "function" ? coinPotionActive() : null;
  const ra = gm && typeof rewindActive === "function" ? rewindActive() : null;
  box.append(el("b", null, (s.d === s.n ? "今日计划 · 已完成" : "今日计划") + (pa ? ` · ${pa.mult} 倍经验中` : "") + (ca ? ` · 金币 ×${ca.mult} 中` : "") + (ra ? ` · 回到过去中（算进${rewindDayText(ra.day)}）` : "")), el("span", "n", `${s.d}/${s.n} 题 · 今日 ${st.today}/${xpGoal} 经验 · 连续 ${st.n} 天${coins}`), bar);
  box.addEventListener("click", () => planGo("plan:"));
  return box;
}
const planSlot = el("div", "plan-slot");
$("main").prepend(planSlot);
function planRefresh() {
  const old = $("planToc");
  if (old) old.replaceWith(planTocItem());
  planSlot.textContent = ""; planSlot.append(planTocItem("planMini"));
  planSlot.hidden = view === "book" || view === "exam" || view === "settings" || view === "shop";
  if (typeof planDoneCheck === "function") planDoneCheck();   // 法语页：第一次做完今日计划时开放商店   // 学习进度页有完整的计划卡，模拟卷不打扰
}
planRefresh();

// 学习进度页最上面的今日计划卡
function planCard() {
  const card = el("section", "card plan-card");
  const p = planGet();
  const head = el("div", "plan-head");
  const d = new Date();
  head.append(el("h3", null, `今日计划 · ${d.getMonth() + 1} 月 ${d.getDate()} 日`));
  if (!p) { card.append(head, el("p", "empty", "正在读取答题记录…")); return card; }
  const s = planStatus(p), st = streakInfo();
  head.append(el("span", "streak" + (st.met ? " on" : ""), `连续 ${st.n} 天`));
  card.append(head);
  if (typeof practiceScopeNote === "function") {
    card.append(el("p", "sub", practiceScopeNote()));
    if (planScope()) card.append(el("p", "sub", "已设难度时，计划只安排标有对应等级的题目；变位可到变位板块单独练习。已完成的题目仍计入今日进度。"));
  }
  const all = el("div", "plan-all");
  const bar = el("span", "pbar"), fill = el("i", "mastery"); fill.style.width = (s.n ? s.d / s.n * 100 : 0) + "%"; bar.append(fill);
  all.append(bar, el("b", null, `${s.d} / ${s.n} 题`));
  card.append(all);
  const list = el("div", "prog-list");
  s.parts.forEach(x => {
    const r = el("button", "prog-row"); r.type = "button";
    const b = el("span", "pbar"), f = el("i", "mastery"); f.style.width = (x.d / x.n * 100) + "%"; b.append(f);
    const num = el("span", "n"); num.append(el("b", null, `${x.d}/${x.n}`), document.createTextNode(x.d >= x.n ? " · 完成" : ""));
    r.append(el("span", "t", x.name), b, num);
    r.addEventListener("click", () => planGo("plan:" + x.k));
    list.append(r);
  });
  card.append(list);
  const left = s.n - s.d;
  const act = el("div", "actions");
  const go = el("button", left ? "btn" : "btn ghost", left ? `开始今日计划（剩 ${left} 题）` : "今日计划已完成"); go.type = "button"; go.id = "planGo";
  go.disabled = !left;
  go.addEventListener("click", () => planGo("plan:"));
  act.append(go);
  card.append(act);
  // 每日经验目标
  const goal = el("div", "plan-goal");
  const gb = el("span", "xp-bar"), gf = el("i"); gf.style.width = Math.min(100, st.today / xpGoal * 100) + "%"; gb.append(gf);
  const lab = el("label", null, "每日目标 ");
  const sel = el("select"); sel.id = "goalSel";
  GOAL_OPTS.forEach(v => { const o = el("option", null, `${v} 经验`); o.value = String(v); if (v === xpGoal) o.selected = true; sel.append(o); });
  sel.addEventListener("change", () => { xpGoal = Number(sel.value); try { localStorage.setItem("fq-goal", String(xpGoal)); } catch (e) {} drawBook(); });
  lab.append(sel);
  goal.append(el("span", null, `今日经验 ${st.today} / ${xpGoal}` + (st.met ? " · 已打卡" : "")), gb, lab);
  card.append(goal);
  if (st.patch) card.append(el("p", "plan-patch", `昨天没达到目标。今天拿到 ${2 * xpGoal} 经验（2 倍目标），或用商店里的时光沙漏回到昨天把题补上，就能保住之前连续的 ${st.patch} 天。`));
  const rule = el("details", "xp-rule");
  rule.append(el("summary", null, "今日计划怎么配"),
    elParts("p", [`每天首次生成；改变难度时仅调整未完成部分：到期该复习的题（最多 ${PLAN_REVIEW_MAX} 道，最该复习的在前）、从最近做的那一轮接着往下的 ${PLAN_NEW} 道新题、最近 60 天答错比例最高的标签里 ${PLAN_WEAK} 道题`, hasConj() && !planScope() ? `，再加 ${PLAN_CONJ} 道动词变位。` : "。", "今天答过一次就算完成。"]),
    el("p", null, "连续打卡：当天经验达到每日目标算打卡。某天没达标，第二天达到 2 倍目标就能补签那一天（不能连着两天都缺），也可以用商店里的时光沙漏回到昨天，把昨天的题补上。做完今日计划奖励 30 金币。"));
  card.append(rule);
  return card;
}
// ---------- 每日任务、金币和商店（多邻国式）：每天 3 个任务，完成得金币；金币买时光沙漏和双倍 / 三倍经验药水 ----------
// 金币的获得、购买、使用都记成记录（game 集合），和答题记录一样跟着账号同步；余额和库存都由记录算出。
// 同一个奖励（某天的某个任务）只算一次，两台设备同时领取也不会重复。
const COIN_TIERS = [10, 15, 20];      // 三个任务：简单 / 中等 / 困难
const COIN_PLAN = 30;  // 做完今日计划（三个任务全部完成改成给一个宝箱）
const POTION_MIN = 15;
// 答对得金币：每答对一题 +1，连对越多给得越多（combo 5 起 2 个，10 起 3 个，20 起 4 个，30 起 5 个封顶）。
// 连对按记录算：答题、变位、背单词各算各的，答错或隔了 10 分钟以上没答就重新算。
// 只算这个日期以后的记录（以前的记录不补发）。
const COIN_ANS_FROM = "2026-11-03";
const COIN_RUN_GAP = 10 * 60e3;
const COIN_CURVE = [[30, 5], [20, 4], [10, 3], [5, 2], [1, 1]];
const coinFor = run => (COIN_CURVE.find(([n]) => run >= n) || [0, 0])[1];
function coinStep(st, key, right, t) {
  const r = st.runs[key] || (st.runs[key] = { n: 0, t: 0 });
  if (t - r.t > COIN_RUN_GAP) r.n = 0;
  r.t = t;
  if (!right) {
    if (r.n && shieldUsed(key, t)) return { coins: 0, run: r.n, shield: true };   // 连对护盾挡下：连对不断
    r.n = 0;
    return { coins: 0, run: 0 };
  }
  r.n++;
  if (dayKey(new Date(t)) < COIN_ANS_FROM) return { coins: 0, run: r.n };   // 游戏模式关着（或还没买）时金币也在后台照常积累
  const c = coinFor(r.n) * coinMult(t) * (typeof langCoinMult === "function" ? langCoinMult(t) : 1);   // 金币药水生效时翻倍；法语页英文模式下再翻倍
  st.coins += c;
  return { coins: c, run: r.n };
}
// 连对护盾：游戏模式下，连对 3 题以上时答错一次，自动用掉一个，连对不断。用掉时记成 use 记录（哪一路、挡的是哪条记录）。
const SHIELD_MIN = 3;
let shieldCache = null;
function shieldUsed(key, t) {
  if (!shieldCache) shieldCache = new Set(gameRaw.filter(g => g.kind === "use" && g.item === "shield").map(g => g.key + "|" + Date.parse(g.ref)));
  return shieldCache.has(key + "|" + t);
}
const streamOf = (d, kind) => kind === "vocab" ? "voc" : d.round === "cj" ? "conj" : "quiz";
function shieldTry(d, kind) {
  if (!gameOn() || !prog || (kind === "vocab" ? d.ok : d.isCorrect) || (kind !== "vocab" && !d.qid)) return false;
  const key = streamOf(d, kind), r = prog.runs[key], t = Date.parse(d.at);
  if (!r || r.n < SHIELD_MIN || t - r.t > COIN_RUN_GAP || !gameLedger().inv.shield) return false;
  gameAdd({ kind: "use", item: "shield", key, ref: d.at, at: d.at });
  comboShielded = key;
  return true;
}
// 宝箱：每天三个任务全部完成得一个（记成 chest 记录），打开时随机给奖励，奖励在打开那一刻记下来
const CHEST_LOOT = [
  [30, { coins: 30 }], [25, { coins: 50 }], [15, { coins: 80 }], [5, { coins: 150 }],
  [12, { item: "shield" }], [8, { item: "x2" }], [3, { item: "rewind" }],
];
const lootText = l => l.coins ? `${l.coins} 金币` : SHOP.find(s => s.id === l.item).name;
function chestOpen() {
  const led = gameLedger(), key = led.chests[0];
  if (!key) return null;
  let roll = Math.random() * CHEST_LOOT.reduce((a, [w]) => a + w, 0), loot = CHEST_LOOT[0][1];
  for (const [w, l] of CHEST_LOOT) { if ((roll -= w) < 0) { loot = l; break; } }
  const it = loot.item && SHOP.find(s => s.id === loot.item);
  if (it && it.max && led.inv[it.id] >= it.max) loot = { coins: Math.round(it.price / 2) };   // 已经存满：换成金币
  gameAdd({ kind: "chest", key, open: true, loot, at: new Date().toISOString() });
  return loot;
}
