function cosBuy(id) {
  const it = COSMETICS.find(c => c.id === id), led = gameLedger();
  if (!it) return "没有这件商品";
  if (led.owned.has(id)) return "已经拥有";
  if (led.coins < it.price) return "金币不够";
  gameAdd({ kind: "buy", item: id, price: it.price, at: new Date().toISOString() });
  cosEquip(it.slot, id);   // 买了直接换上
  return "";
}
function cosEquip(slot, id) {
  if (slot === "skin") cosTrialEnd();
  gameAdd({ kind: "equip", slot, item: id || null, at: new Date().toISOString() });
  cosApply();
}

// 背景区域的手感：往外拉有阻力（只跟手 35%–40%），松手时如果没拉到头，就自动回弹到内容边上；拉到头就停在背景全貌
const COS_DRAG = .38, COS_WHEEL = .35, COS_SNAP = .5, COS_BACK = .3;
let cosFull = null;   // 当前停在哪一边的背景全貌（"top" / "bot"），用来判断是“拉出去”还是“往回滑”
let cosTouch = null, cosSnapT = 0, cosWheel = null;
function cosZone() {
  const top = document.getElementById("skinRevealTop"), bot = document.getElementById("skinReveal");
  if (!top || !bot) return null;
  const y = window.scrollY, topEdge = top.offsetHeight, botEdge = Math.max(topEdge, bot.offsetTop - window.innerHeight);   // 内容比屏幕短时，两边的边缘重合
  const max = document.documentElement.scrollHeight - window.innerHeight;
  return { y, topEdge, botEdge, max, inTop: y < topEdge - 1, inBot: y > botEdge + 1, topFull: y <= 2, botFull: y >= max - 2 };
}
// 往 delta 方向滚：在内容里照常滚，超出内容边缘、进入背景区域的那一段按 k 打折（阻力）
function cosResist(z, delta, k) {
  const y = z.y;
  if (delta < 0) {
    if (y <= z.topEdge) return y + delta * k;
    const free = y - z.topEdge;
    return -delta <= free ? y + delta : z.topEdge - (-delta - free) * k;
  }
  if (y >= z.botEdge) return y + delta * k;
  const free = z.botEdge - y;
  return delta <= free ? y + delta : z.botEdge + (delta - free) * k;
}
