// 商店里的“外观”部分
function cosPreview(it) {
  const box = el("div", "cos-prev");
  if (it.slot === "coin") box.append(el("i", "coin cs-" + it.id));
  else if (it.slot === "skin") { const sw = el("div", "sk-swatch sk-" + it.id), c = el("div", "sk-card"); c.append(el("i"), document.createTextNode("Aa")); sw.append(c); box.append(sw); }
  else if (it.slot === "frame") { const b = el("div", "xp-badge fr-" + it.id); b.append(el("small", null, "Lv"), el("b", null, "12")); box.append(b); }
  else box.innerHTML = COS_PX["fx_" + (it.id === "chime" ? "sound" : it.id)] || "";
  return box;
}
function cosShop(note) {
  const led = gameLedger(), eq = cosEquipped();
  const ownN = COSMETICS.filter(c => led.owned.has(c.id)).length;
  const wrap = foldSec("cos", "商店 · 外观", `金币皮肤、主题配色、连对特效、称号框 · 已拥有 ${ownN} / ${COSMETICS.length}`);
  wrap.classList.add("cos-shop");
  if (cosTrialAllowed()) {
    const hint = el("p", "shop-note cos-trial-note"); hint.setAttribute("role", "status");
    wrap.append(hint);
    queueMicrotask(cosTrialRefresh);
  }
  wrap.addEventListener("toggle", () => { if (!wrap.open && cosTrialSkin) { cosTrialEnd(); cosApply(); } });
  COS_SLOTS.forEach(([slot, label]) => {
    const items = COSMETICS.filter(c => c.slot === slot);
    wrap.append(el("div", "cos-sec", label));
    const grid = el("div", "cos-grid");
    items.forEach(it => {
      const own = led.owned.has(it.id), on = eq[slot] === it.id;
      const card = el("div", "cos-item" + (on ? " on" : ""));
      card.append(cosPreview(it), el("b", null, it.name), el("span", "cos-desc", it.desc));
      const btn = el("button", own ? (on ? "btn ghost" : "btn") : "btn ghost"); btn.type = "button"; btn.id = "cos-" + it.id;
      if (!own) {
        btn.append(document.createTextNode("购买 "), coinEl(it.price));
        btn.disabled = led.coins < it.price;
        let sure = false;
        btn.addEventListener("click", () => {
          if (!sure) { sure = true; btn.textContent = `确认花 ${it.price} 金币`; return; }
          const err = cosBuy(it.id);
          if (err) { note.textContent = err; return; }
          xpToast(`花了 ${it.price} 金币，已经换上`, `买到了：${it.name}`);
          shopRedraw();
        });
      } else {
        btn.textContent = on ? "卸下" : "换上";
        btn.addEventListener("click", () => { cosEquip(slot, on ? null : it.id); shopRedraw(); });
      }
      card.append(btn);
      if (it.slot === "skin" && !own && cosTrialAllowed()) {
        const trial = el("button", "btn ghost", cosTrialSkin === it.id ? "结束试用" : "试用");
        trial.type = "button"; trial.dataset.skinTrial = it.id;
        trial.setAttribute("aria-pressed", String(cosTrialSkin === it.id));
        trial.addEventListener("click", () => cosTrialToggle(it.id));
        card.append(trial);
      }
      grid.append(card);
    });
    wrap.append(grid);
  });
  wrap.append(el("p", "shop-note", "外观买一次永久拥有，同一类一次用一个，随时可以换上或卸下。关掉游戏模式时显示默认外观。"));
  return wrap;
}

// 连对特效：答对时从 combo 标记的位置冒出来
function cosFx(anchor, n) {
  const fx = document.documentElement.dataset.fx;
  if (fx && anchor && !matchMedia("(prefers-reduced-motion: reduce)").matches) {
    const r = anchor.getBoundingClientRect(), x0 = r.left + r.width / 2, y0 = r.top + r.height / 2;
    const count = n % 10 === 0 ? 30 : n % 5 === 0 ? 20 : 12;
    const colors = fx === "tricolor" ? ["#1f4fd8", "#ffffff", "#e5243b"] : ["#ef476f", "#118ab2", "#ffd166", "#06d6a0", "#9b5de5", "#ff8c42"];
    for (let i = 0; i < count; i++) {
      const p = el("i", "fx-p fx-" + fx);
      const a = Math.random() * Math.PI * 2, d = (fx === "tricolor" ? 40 : 30) + Math.random() * (fx === "tricolor" ? 50 : 60);
      p.style.cssText = `--x0:${x0}px;--y0:${y0}px;--dx:${Math.cos(a) * d}px;--dy:${Math.sin(a) * d - (fx === "confetti" ? 40 : 0)}px;--rot:${Math.round(Math.random() * 720 - 360)}deg;background:${colors[i % colors.length]}`;
      if (fx === "tricolor" && colors[i % colors.length] === "#ffffff") p.style.boxShadow = "0 0 0 1px rgba(0,0,0,.15)";
      document.body.append(p);
      setTimeout(() => p.remove(), 1200);
    }
  }
  // 连对音效：combo 10、20、30……时放一小段像素音乐
  if (document.documentElement.dataset.sound && n >= 10 && n % 10 === 0) cosChime(n);
}
let cosAudio = null;
function cosChime(n) {
  try {
    cosAudio = cosAudio || new (window.AudioContext || window.webkitAudioContext)();
    const ctx = cosAudio, t0 = ctx.currentTime + .02;
    const notes = n % 30 === 0 ? [523, 659, 784, 1047, 784, 1047, 1319] : [523, 659, 784, 1047];
    notes.forEach((f, i) => {
      const o = ctx.createOscillator(), g = ctx.createGain();
      o.type = "square"; o.frequency.value = f;
      const t = t0 + i * .09;
      g.gain.setValueAtTime(0, t); g.gain.linearRampToValueAtTime(.08, t + .01); g.gain.linearRampToValueAtTime(0, t + .085);
      o.connect(g); g.connect(ctx.destination); o.start(t); o.stop(t + .1);
    });
  } catch (e) {}
}
cosReady = true;
cosApply();
