function tourChapterList(card){
 const list=el('div','tour-chapters');
 TOUR_CHAPTERS.forEach((chapter,k)=>{
  const group=el('details','tour-chapter');group.open=tourNextStop()?.chapter===k;
  const summary=el('summary',null,chapter.lv+' · '+tourTr(chapter.title));group.append(summary,el('p','sub',tourTr(chapter.task)));
  TOUR_ROUTE.filter(s=>s.chapter===k).forEach(s=>{
   const row=el('div','tour-route-row'),open=tourCanStart(s.id),best=tourBest()[s.id]||0;
   const b=tourButton(tourNo(s)+' · '+stopName(s),()=>{tourSel=s.parent||s.id;tourMapName=s.map;if(open)tourStart(s.id);else renderTour();},true);
   b.setAttribute('aria-label',tourNo(s)+' · '+stopName(s)+(open?'':tourText(' · 未解锁，查看目标',' · Locked, view goal',' · Verrouillé, voir l’objectif')));
   row.append(b,el('span',null,tourGoal(s)+' · '+s.lv),pxStars(best,3));
   row.append(el('small','sub',tourCatalog(s)));
   if(!open)row.append(el('small',null,tourText(`先完成第 ${tourNextStop()?.no} 关`,`Complete level ${tourNextStop()?.no} first`,`Terminez d'abord l'étape ${tourNextStop()?.no}`)));
   if(tourHasOral(s)&&open){const status=tourOralLatest(s.id)?.status;row.append(tourButton(status==='review'?tourText('待复练 · 口语','Speaking · Review due','Oral · À reprendre'):tourText('练口语','Practise speaking','Pratiquer l’oral'),()=>tourOralStart(s.id),true));}
   group.append(row);
  });list.append(group);
 });card.append(list);
}
