// ---------- 连对 combo：连续答对计数，答错清零（答题、变位、背单词各自计数） ----------
// 连对按做题记录算（和金币、连对护盾用同一个数）：隔 10 分钟以上没答也重新算。不受游戏模式影响，一直显示。
const comboLocal = {};        // 记录还没读完时的临时计数
let comboShielded = "";       // 刚被连对护盾挡下的那一路（quiz / conj / voc）
function comboVal(key) {
  if (typeof prog !== "undefined" && prog && prog.runs) {
    const r = prog.runs[key];
    return r && Date.now() - r.t <= COIN_RUN_GAP ? r.n : 0;
  }
  return comboLocal[key] || 0;
}
// 答完一题后调用（在记录之后）：更新这一路的 combo 标记，返回当前连对数
function comboHit(key, ok) {
  const shield = !ok && comboShielded === key;
  comboShielded = "";
  comboLocal[key] = ok ? (comboLocal[key] || 0) + 1 : shield ? comboLocal[key] || 0 : 0;
  document.querySelectorAll(`.v-combo[data-k="${key}"]`).forEach(b => comboDraw(b, ok || shield, shield));
  const n = comboVal(key);
  if (ok && n >= 2 && typeof cosFx === "function") cosFx(document.querySelector(`.v-combo[data-k="${key}"]:not([hidden])`), n);
  return n;
}
// 题卡标签行里的 combo 标记：连对 2 题起显示，10 题以上换深色
function comboBadge(key) {
  const b = el("span", "v-combo"); b.dataset.k = key;
  comboDraw(b, false);
  return b;
}
function comboDraw(b, bump, shield) {
  const n = comboVal(b.dataset.k);
  b.textContent = n >= 2 ? (shield ? "🛡 " : "") + `combo ${n}` : "";
  b.hidden = n < 2;
  b.classList.toggle("hot", n >= 10);
  b.classList.toggle("shielded", !!shield);
  if (bump && n >= 2) { b.classList.remove("bump"); void b.offsetWidth; b.classList.add("bump"); }
}
// ---------- 账号登录与多设备同步（只在公开网站上启用；Claude 页面的记录本来就跟着 Claude 账号走） ----------
// 登录：邮箱验证码（Supabase Auth）。记录存在 Supabase 的 records 表里，每个用户只能读写自己的记录（见 quiz-site/supabase/schema.sql）。
// 记录只增不改，所以同步 = 本机和云端取并集（按内容指纹去重）；离线时做的题联网后补传。不登录时和以前一样只存在本机。
const SYNC_URL = "https://aitqcayhvurtbpduxlvc.supabase.co";
const SYNC_KEY = "sb_publishable_gYcafzI23rtTsuCYWQWlrA_5sXku0ez";   // 公开的 publishable key（权限由数据库的行级安全策略限制）
const SYNC_NS = "fq-";            // 本页在浏览器里的存储前缀（随机分析页构建时换成 sq-）
const SYNC_AUTH = "quiz-auth";    // 登录状态：两个练习页共用，登录一次就行
const SYNC_ON = typeof claude === "undefined";
let syncState = { busy: false, last: 0, err: "", queue: [], timer: 0 };

// 记录内容的指纹（cyrb53）
function syncHash(str) {
  let h1 = 0xdeadbeef, h2 = 0x41c6ce57;
  for (let i = 0; i < str.length; i++) { const c = str.charCodeAt(i); h1 = Math.imul(h1 ^ c, 2654435761); h2 = Math.imul(h2 ^ c, 1597334677); }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(36);
}
const syncKeyOf = d => syncHash(recKey(d));
function syncAuth() { try { return JSON.parse(localStorage.getItem(SYNC_AUTH) || "null"); } catch (e) { return null; } }
function syncAccountChanged() {
  if (typeof usageAccountChanged === "function") usageAccountChanged();
  clearTimeout(syncRetryTimer); clearTimeout(syncState.timer); syncState.timer = 0; syncState.queue = []; syncState.last = 0;
  if (typeof oralOnAccountChange === "function") oralOnAccountChange();
  if (typeof petOnAccountChange === "function") petOnAccountChange();
  if (typeof pomoAccountChange === "function") pomoAccountChange();
  if (typeof feedbackOnAccountChange === "function") feedbackOnAccountChange();
}
function syncSaveAuth(a) {
  const previous = syncAuth()?.uid || "";
  try { if (a) localStorage.setItem(SYNC_AUTH, JSON.stringify(a)); else localStorage.removeItem(SYNC_AUTH); } catch (e) {}
  if (previous !== (syncAuth()?.uid || "")) syncAccountChanged();
}
function syncAssertAccount(uid) {
  if ((syncAuth()?.uid || "") !== uid) { const e = new Error("Account changed"); e.code = "account"; throw e; }
}
function syncSaveSession(j) {
  const old = syncAuth() || {};
  syncSaveAuth({ access_token: j.access_token, refresh_token: j.refresh_token, expires_at: j.expires_at || Math.floor(Date.now() / 1000) + (j.expires_in || 3600),
    email: (j.user && j.user.email) || old.email || "", uid: (j.user && j.user.id) || old.uid || "" });
}
// Refresh failures are not all sign-outs: only a confirmed revoked/missing session is terminal.
const syncAuthStamp = a => a ? JSON.stringify([a.uid,a.access_token,a.refresh_token]) : '';
const syncFlights = new Map();
let syncRetryTimer = 0;
function syncAuthError(code, message='Session unavailable') { const e=new Error(message);e.code=code;return e; }
function syncSameSession(a) { return syncAuthStamp(syncAuth())===syncAuthStamp(a); }
function syncRetryState(a) {
  try {const r=JSON.parse(localStorage.getItem('quiz-auth-retry')||'null');return r?.session===syncHash(syncAuthStamp(a))?r:null;}catch(e){return null;}
}
function syncRetryLater(a, response) {
  if(!syncSameSession(a))return;
  const prior=syncRetryState(a),count=Math.min(6,(prior?.count||0)+1);
  const raw=response?.headers?.get('Retry-After');
  const retry=raw?(Number.isFinite(Number(raw))?Number(raw)*1000:Date.parse(raw)-Date.now()):0;
  const delay=Math.min(300000,Math.max(5000*Math.pow(2,count-1),Number.isFinite(retry)?retry:0));
  const state={session:syncHash(syncAuthStamp(a)),count,until:Date.now()+delay};
  try{localStorage.setItem('quiz-auth-retry',JSON.stringify(state));}catch(e){}
  clearTimeout(syncRetryTimer);
  syncRetryTimer=setTimeout(()=>{if(syncSameSession(a)&&navigator.onLine)syncNow(true);},delay+50);
}
// Web Locks coordinate French, stochastic and other tabs on the same origin.
// Older browsers use a short-lived advisory lease; responses always compare the exact session.
async function syncRefreshLock(run) {
  if(navigator.locks?.request){
    const ac=new AbortController(),timer=setTimeout(()=>ac.abort(),20000);
    try{return await navigator.locks.request('quiz-auth-refresh',{signal:ac.signal},run);}
    finally{clearTimeout(timer);}
  }
  const key='quiz-auth-refresh-lock',owner=crypto.randomUUID(),deadline=Date.now()+20000;
  const read=()=>{try{return JSON.parse(localStorage.getItem(key)||'null');}catch(e){return null;}};
  while(Date.now()<deadline){
    const lease=read();
    if(!lease||lease.until<Date.now()){
      try{localStorage.setItem(key,JSON.stringify({owner,until:Date.now()+16000}));}catch(e){return run();}
      await new Promise(resolve=>setTimeout(resolve,60+Math.random()*60));
      if(read()?.owner===owner){
        try{return await run();}finally{if(read()?.owner===owner)try{localStorage.removeItem(key);}catch(e){}}
      }
    }
    await new Promise(resolve=>setTimeout(resolve,150));
  }
  throw syncAuthError('temporary','Refresh coordination timed out');
}
async function syncToken(force=false, rejectedToken=null) {
  const initial=syncAuth();if(!initial)return null;
  if(!force&&Date.now()/1000<initial.expires_at-60)return initial.access_token;
  if(force&&rejectedToken&&initial.access_token!==rejectedToken&&Date.now()/1000<initial.expires_at-60)return initial.access_token;
  const key=syncAuthStamp(initial);
  if(syncFlights.has(key))return syncFlights.get(key);
  const task=syncRefreshLock(async()=>{
    syncAssertAccount(initial.uid||'');
    const a=syncAuth();
    if(!syncSameSession(initial))return a.access_token;
    if(!force&&Date.now()/1000<a.expires_at-60)return a.access_token;
    if((syncRetryState(a)?.until||0)>Date.now())throw syncAuthError('temporary','Refresh retry pending');
    if(!a.refresh_token)throw syncAuthError('temporary','Missing refresh credentials');
    const ac=new AbortController(),timer=setTimeout(()=>ac.abort(),12000);
    let r,j;
    try{
      r=await fetch(`${SYNC_URL}/auth/v1/token?grant_type=refresh_token`,{method:'POST',headers:{apikey:SYNC_KEY,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:a.refresh_token}),signal:ac.signal});
      try{j=await r.json();}catch(e){j={};}
    }catch(e){syncRetryLater(a);throw syncAuthError('temporary','Session refresh temporarily unavailable');}
    finally{clearTimeout(timer);}
    syncAssertAccount(a.uid||'');
    if(!syncSameSession(a))return syncAuth()?.access_token;
    if(!r.ok){
      const terminal=['refresh_token_not_found','refresh_token_already_used','session_not_found','session_expired','user_not_found','user_banned'].includes(j.code||j.error_code);
      if(r.status>=400&&r.status<500&&r.status!==429&&terminal){
        syncSaveAuth(null);syncState.err='登录已过期，请重新登录';syncRefreshView();throw syncAuthError('auth');
      }
      syncRetryLater(a,r);throw syncAuthError(r.status===429?'rate':'temporary','Session refresh temporarily unavailable');
    }
    if(!j.access_token||!j.refresh_token||j.user?.id!==a.uid){syncRetryLater(a);throw syncAuthError('temporary','Incomplete refresh response');}
    syncSaveSession(j);
    try{localStorage.removeItem('quiz-auth-retry');}catch(e){}
    clearTimeout(syncRetryTimer);return syncAuth()?.access_token;
  }).catch(e=>{if(e.code!=='auth'&&e.code!=='account'&&e.code!=='rate'&&e.code!=='temporary'){syncRetryLater(initial);throw syncAuthError('temporary');}throw e;});
  syncFlights.set(key,task);
  try{return await task;}finally{if(syncFlights.get(key)===task)syncFlights.delete(key);}
}
async function syncFetch(path, opt = {}, auth = true, uid = null) {
  const expected=auth?(uid??syncAuth()?.uid??''):null;
  const headers = { apikey: SYNC_KEY, 'Content-Type': 'application/json', ...(opt.headers || {}) };
  let tok=null;
  if(auth){syncAssertAccount(expected);tok=await syncToken();syncAssertAccount(expected);if(!tok)throw syncAuthError('auth','未登录');headers.Authorization='Bearer '+tok;}
  let r=await fetch(SYNC_URL+path,{...opt,headers});
  if(auth)syncAssertAccount(expected);
  // A stale access token gets one coordinated refresh. A generic API 401 never erases a session.
  if(auth&&r.status===401&&!opt.signal?.aborted){
    const fresh=await syncToken(true,tok);syncAssertAccount(expected);
    if(fresh){headers.Authorization='Bearer '+fresh;r=await fetch(SYNC_URL+path,{...opt,headers});syncAssertAccount(expected);}
  }
  if(!r.ok){
    let msg='';try{const j=await r.json();msg=j.msg||j.message||j.error_description||j.error||'';}catch(e){}
    const e=new Error(msg||'HTTP '+r.status);e.status=r.status;e.code=r.status===429?'rate':r.status===401?'permission':'';throw e;
  }
  const text=await r.text();if(auth)syncAssertAccount(expected);return text?JSON.parse(text):null;
}

// 本机的记录（和公开网站的本地数据库同一份）
const syncLocal = c => { try { return JSON.parse(localStorage.getItem(SYNC_NS + "db-" + c) || "[]"); } catch (e) { return []; } };
const syncStore = (c, arr) => { try { localStorage.setItem(SYNC_NS + "db-" + c, JSON.stringify(arr)); } catch (e) {} };
const syncRow = (c, d) => ({ app: REC_APP, coll: c, key: syncKeyOf(d), data: d });
// 伙伴配置和留言奖励按账号隔离；既有答案/金币沿用原站的本机合并规则。
const syncPetAllowed = (c, d, uid) => c !== "game" || !["pet", "pet-study", "pet-affinity-migration", "pet-unlock", "feedback_reward", "share_reward", "survey_reward"].includes(d?.kind) || !!uid && d.scope === "user:" + uid;
// Reward records are issued by the server only; never upload them from any device.
const syncServerRecord = (c, d) => c === "game" && ["feedback_reward", "share_reward", "survey_reward"].includes(d?.kind);
async function syncUpload(rows, uid = syncAuth()?.uid || "") {
  const own = rows.filter(r => syncPetAllowed(r.coll, r.data, uid) && !syncServerRecord(r.coll, r.data));
  for (let i = 0; i < own.length; i += 500) {
    syncAssertAccount(uid);
    await syncFetch("/rest/v1/records?on_conflict=user_id,app,coll,key", {
      method: "POST", headers: { Prefer: "resolution=ignore-duplicates,return=minimal" }, body: JSON.stringify(own.slice(i, i + 500)),
    }, true, uid);
  }
}
// 完整同步：拉取云端全部记录合并进本机，再把本机有、云端没有的传上去
async function syncNow(force) {
  if (!SYNC_ON || !syncAuth() || !navigator.onLine || syncState.busy) return;
  if (!force && Date.now() - syncState.last < 60e3) return;
  const uid = syncAuth().uid || "";
  syncState.busy = true; syncDraw();
  try {
    const remote = [];
    for (let off = 0; ; off += 1000) {
      const rows = await syncFetch(`/rest/v1/records?select=coll,key,data&app=eq.${REC_APP}&order=id.asc&limit=1000&offset=${off}`, {}, true, uid);
      syncAssertAccount(uid);
      remote.push(...rows);
      if (rows.length < 1000) break;
    }
    if (typeof petMigrateRemote === "function") petMigrateRemote(remote, uid);
    const prepared = typeof vLvSyncPrepare === "function" ? vLvSyncPrepare(remote) : 0;
    let added = 0;
    const up = [];
    for (const c of REC_COLLS) {
      const loc = syncLocal(c), lk = new Set(loc.map(syncKeyOf));
      const rk = new Set();
      let n = 0;
      remote.forEach(r => {
        if (r.coll !== c || !syncPetAllowed(c, r.data, uid)) return;
        rk.add(r.key);
        const localKey = syncServerRecord(c, r.data) ? syncKeyOf(r.data) : r.key;
        if (!lk.has(localKey)) { loc.push(r.data); lk.add(localKey); n++; }
      });
      if (n) { syncStore(c, loc); added += n; }
      loc.forEach(d => { if (!syncPetAllowed(c, d, uid) || syncServerRecord(c, d)) return; const k = syncKeyOf(d); if (!rk.has(k)) { up.push({ app: REC_APP, coll: c, key: k, data: d }); rk.add(k); } });
    }
    await syncUpload(up, uid);
    syncAssertAccount(uid);
    syncState.last = Date.now(); syncState.err = "";
    syncState.lastUp = up.length; syncState.lastDown = added;
    if (added || prepared) await syncReload();
    if (typeof socPushSoon === "function") socPushSoon();   // 好友排行榜上的资料跟着更新（只有法语页有）
  } catch (e) {
    if (e.code !== "account" && (syncAuth()?.uid || "") === uid) {
      syncState.err = e.code === "auth" ? "登录已过期，请重新登录" : "同步没成功（可能是网络问题），稍后会自动再试";
      // Only the refresh endpoint can confirm terminal session invalidation.
    }
  }
  syncState.busy = false; syncDraw();
  if ((syncAuth()?.uid || "") !== uid && syncAuth()) setTimeout(() => syncNow(true), 0);
}
// 答完一题：把新记录攒一小会儿再一起传
function syncPush(c, d) {
  if (!SYNC_ON || !syncAuth()) return;
  const uid = syncAuth().uid || "";
  if (!syncPetAllowed(c, d, uid) || syncServerRecord(c, d)) return;
  syncState.queue.push(syncRow(c, d));
  clearTimeout(syncState.timer);
  syncState.timer = setTimeout(async () => {
    const rows = syncState.queue.splice(0);
    if (!rows.length || !navigator.onLine) return;   // 没网：下次完整同步时会补传
    try { await syncUpload(rows, uid); syncAssertAccount(uid); syncState.last = Date.now(); syncState.err = ""; } catch (e) {}
    syncDraw();
  }, 1500);
}
// 云端拉下来新记录后：重新读一遍本机记录，刷新进度、经验和页面
async function syncReload() {
  if (!dbRef) return;
  const get = async c => (await dbRef.collection(c).get()).docs.map(d => d.data());
  gameReset(await get("game"));
  progReset(await get("answers"), await get("vocab"));
  progEnsure();
  if (typeof petOnDataReady === "function") petOnDataReady();
  bookCache = null;
  if (typeof vStats !== "undefined") vStats = null;
  planRefresh();
  if (view === "tour" && typeof renderTour === "function" && !tourRun && !tourOral) renderTour();
  else if (view === "book") renderBook();
  else if (view === "cafe" && typeof renderCafe === "function") renderCafe(true);
  else if (view === "vocab" && typeof renderVocab === "function" && !vSess) renderVocab();
}
// 登录状态变了：重画“账号与同步”所在的设置页
function syncRefreshView() { if (view === "settings" && typeof renderSettings === "function") renderSettings(); }
function syncLogout() { syncSaveAuth(null); syncState.err = ""; syncDraw(); syncRefreshView(); }
async function syncDeleteAccount() {
  const uid=syncAuth()?.uid||"";
  await syncFetch("/rest/v1/rpc/delete_my_account", { method: "POST", body: "{}" },true,uid);
  syncAssertAccount(uid);
  try { if (typeof pomoDeleteAccount === "function") await pomoDeleteAccount(uid); } finally { syncLogout(); }
}
if (SYNC_ON) {
  addEventListener("storage", e => {
    if (e.key !== SYNC_AUTH) return;
    let before = "", after = "";
    try { before = JSON.parse(e.oldValue || "null")?.uid || ""; after = JSON.parse(e.newValue || "null")?.uid || ""; } catch (err) {}
    if (before !== after) { syncAccountChanged(); syncRefreshView(); syncNow(true); }
  });
  addEventListener("online", () => syncNow(true));
  document.addEventListener("visibilitychange", () => { if (document.visibilityState === "visible") syncNow(false); });
  setInterval(() => { if (document.visibilityState === "visible") syncNow(false); }, 5 * 60e3);
}

// 学习进度页最上面的“账号与同步”卡
function syncStatusText() {
  if (syncState.busy) return "正在同步…";
  if (syncState.err) return syncState.err;
  if (!syncState.last) return navigator.onLine ? "还没有同步" : "现在没有网络，联网后会自动同步";
  const t = new Date(syncState.last);
  return `已同步 · ${String(t.getHours()).padStart(2, "0")}:${String(t.getMinutes()).padStart(2, "0")}`;
}
function syncDraw() { document.querySelectorAll(".sync-status").forEach(e => { e.textContent = syncStatusText(); e.classList.toggle("bad", !!syncState.err); }); }
function syncCard() {
  if (!SYNC_ON) return null;
  const card = el("section", "card sync-card");
  const a = syncAuth();
  const head = el("div", "plan-head");
  head.append(el("h3", null, "账号与同步"));
  card.append(head);
  card.append(el("p", "sub", "此设备会自动保持登录，无需保存密码。正常重新打开无需验证码；退出登录、清除网站数据或会话失效后需重新验证。无痕窗口、其他浏览器或不同设备需分别登录。"));
  const note = el("p", "sync-msg");
  if(!a&&syncState.err)card.append(el("p","sync-msg",syncState.err));
  if (a) {
    head.append(el("span", "sync-status", syncStatusText()));
    card.append(el("p", "sync-who", `已登录：${a.email || "（邮箱）"}。在其他设备上用同一个邮箱登录，做题记录会自动同步。`));
    const act = el("div", "actions");
    const now = el("button", "btn ghost", "立即同步"); now.type = "button"; now.id = "syncNowBtn";
    now.addEventListener("click", () => syncNow(true));
    const out = el("button", "btn ghost", "退出登录"); out.type = "button";
    out.addEventListener("click", syncLogout);
    const del = el("button", "btn ghost danger", "删除账号"); del.type = "button";
    let sure = false;
    del.addEventListener("click", async () => {
      if (!sure) { sure = true; del.textContent = "再点一次：删除账号和云端记录"; note.textContent = "删除后云端的记录无法恢复；这台设备上的记录会保留。"; return; }
      del.disabled = true;
      try { await syncDeleteAccount(); } catch (e) { note.textContent = "删除没成功，请稍后再试。"; del.disabled = false; }
    });
    act.append(now, out, del);
    card.append(act, note);
    syncDraw();
  } else {
    card.append(el("p", "sync-who", "用邮箱登录后，在手机、iPad、电脑上登录同一个邮箱，做题记录会自动同步。不登录也能照常做题，记录只存在这台设备上。"));
    const row = el("div", "sync-row");
    const email = el("input"); email.type = "email"; email.id = "syncEmail"; email.placeholder = "你的邮箱"; email.autocomplete = "email"; email.setAttribute("aria-label", "邮箱");
    const send = el("button", "btn", "发送验证码"); send.type = "button"; send.id = "syncSend";
    row.append(email, send);
    const row2 = el("div", "sync-row"); row2.hidden = true;
    const code = el("input"); code.type = "text"; code.id = "syncCode"; code.inputMode = "numeric"; code.autocomplete = "one-time-code"; code.placeholder = "邮件里的验证码（一串数字）"; code.setAttribute("aria-label", "验证码");
    const go = el("button", "btn", "登录"); go.type = "button"; go.id = "syncLogin";
    row2.append(code, go);
    send.addEventListener("click", async () => {
      const em = email.value.trim();
      if (!/^\S+@\S+\.\S+$/.test(em)) { note.textContent = "请填写正确的邮箱地址。"; return; }
      send.disabled = true; note.textContent = "正在发送…";
      try {
        await syncSendCode(em);
        row2.hidden = false; code.focus();
        note.textContent = `验证码已发到 ${em}，几分钟内有效。没收到的话看看垃圾邮件。`;
      } catch (e) { note.textContent = e.code === "rate" ? "发送太频繁了，请过一会儿再试。" : "发送没成功，请检查邮箱或稍后再试。"; }
      send.disabled = false; send.textContent = "重新发送";
    });
    const login = async () => {
      const c = code.value.replace(/\s/g, "");
      if (!/^\d{6,10}$/.test(c)) { note.textContent = "请填写邮件里的验证码。"; return; }
      go.disabled = true; note.textContent = "正在登录…";
      try { await syncVerify(email.value.trim(), c); syncRefreshView(); }
      catch (e) { note.textContent = "验证码不对或已过期，请重新发送。"; go.disabled = false; }
    };
    go.addEventListener("click", login);
    code.addEventListener("keydown", e => { if (e.key === "Enter") login(); });
    const priv = el("details", "xp-rule");
    priv.append(el("summary", null, "隐私说明"),
      el("p", null, "登录后会在云端（Supabase）保存：你的邮箱，以及做题、背单词、金币和道具的记录。这些记录用于设备同步与学习功能。法语页管理员可查看每日使用时长和各板块作答数量；页面可见时长默认开启，可在功能设置中关闭。不向其他普通用户公开个人学习明细。"),
      el("p", null, "随时可以在这里“删除账号”，云端的账号和记录会一起删除；这台设备上的记录不受影响。"));
    card.append(row, row2, note, priv);
  }
  return card;
}
async function syncSendCode(email) { await syncFetch("/auth/v1/otp", { method: "POST", body: JSON.stringify({ email, create_user: true }) }, false); }
async function syncVerify(email, token) {
  const started=syncAuthStamp(syncAuth());
  const j = await syncFetch("/auth/v1/verify", { method: "POST", body: JSON.stringify({ type: "email", email, token }) }, false);
  if(syncAuthStamp(syncAuth())!==started)throw syncAuthError("account");
  syncSaveSession(j);
  await syncNow(true);
}
