function fbSaveReward(reward, uid) {
  if (!uid || fbUid() !== uid || !reward || reward.kind !== "feedback_reward" || reward.scope !== "user:" + uid || reward.key !== "feedback:first" || reward.coins !== 800) return;
  // Save the server-issued record locally without uploading it back as a client-created reward.
  const list = syncLocal("game").filter(g => !(g.kind === "feedback_reward" && g.scope === reward.scope));
  list.push(reward); syncStore("game", list);
  if (typeof gameRaw !== "undefined") {
    gameRaw = gameRaw.filter(g => !(g.kind === "feedback_reward" && g.scope === reward.scope));
    gameRaw.push(reward);
  }
  if (typeof planRefresh === "function") planRefresh();
  if (typeof socPushSoon === "function") socPushSoon();
}

// browse = counts only; the optional voting controls appear only after answering.
function pictureFeedback(w, browse = false, onInteract = () => {}, compact = false) {
  const root = el("div", "picture-feedback"); root.dataset.noi18n = "";
  const key = vPic(w); root.dataset.picture = key;
  const heading = el("span", "fb-caption", fbText("picture"));
  const votes = el("div", "fb-votes");
  const up = browse ? el("span", "fb-vote") : fbButton("", "fb-vote");
  const down = browse ? el("span", "fb-vote") : fbButton("", "fb-vote");
  const note = el("span", "fb-note", fbText("loading")); note.setAttribute("role", "status");
  const retry = fbButton(fbText("retry"), "fb-link"); retry.hidden = true;
  let data = null, busy = false, revision = 0, desired = null;
  const draw = () => {
    up.textContent = "👍 " + fbText("like") + " " + (data ? data.likes : "—");
    down.textContent = "😞 " + fbText("dislike") + (data && Object.hasOwn(data, "dislikes") ? " " + data.dislikes : "");
    if (!browse) for (const [b, n] of [[up, 1], [down, -1]]) {
      b.disabled = busy || !data;
      b.setAttribute("aria-pressed", String(data?.mine === n));
    }
  };
  const reload = async () => {
    const run = ++revision; data = null; busy = true; desired = null; note.textContent = fbText("loading"); retry.hidden = true; draw();
    try {
      const next = await fbRpc("picture_feedback", { p_picture: key }, true);
      if (run !== revision || !root.isConnected) return;
      data = next; note.textContent = browse || compact ? "" : fbText("optional");
    } catch (e) {
      if (run !== revision || e.code === "account" || !root.isConnected) return;
      note.textContent = fbText("failed"); retry.hidden = false;
    } finally { if (run === revision) { busy = false; draw(); } }
  };
  const save = async target => {
    if (busy) return;
    onInteract();
    if (!fbUid()) { note.replaceChildren(document.createTextNode(fbText("login") + " · "), fbLoginLink()); return; }
    const run = ++revision; busy = true; desired = target; retry.hidden = true; draw();
    try {
      const next = await fbRpc("set_picture_feedback", { p_picture: key, p_vote: target });
      if (run !== revision || !root.isConnected) return;
      data = next; desired = null; note.textContent = fbText(target ? "saved" : "removed");
    } catch (e) {
      if (run !== revision || e.code === "account" || !root.isConnected) return;
      note.textContent = fbText("saveFailed"); retry.hidden = false;
    } finally { if (run === revision) { busy = false; draw(); } }
  };
  if (!browse) {
    up.addEventListener("click", () => save(data?.mine === 1 ? 0 : 1));
    down.addEventListener("click", () => save(data?.mine === -1 ? 0 : -1));
    const target = el("span", "fb-target"); target.append(vImg(w, "fb-thumb"), el("b", null, vLabel(w)));
    if(!compact)root.append(target);
  }
  retry.addEventListener("click", () => desired === null ? reload() : save(desired));
  votes.append(up, down); root.append(votes, note, retry); draw();
  const item = { root, reload }; fbPictures.forEach(x => { if (!x.root.isConnected) fbPictures.delete(x); }); fbPictures.add(item);
  // Wait for the caller to attach the result before rendering an asynchronous response.
  queueMicrotask(reload);
  return root;
}

function feedbackSettings(wrap) {
  wrap.append(avatarSettings());
  const section = el("section", "card fb-settings"); section.dataset.noi18n = "";
  section.append(el("h3", null, fbText("title")), el("p", "sub", fbText("intro"))); wrap.append(section);
  if (!SYNC_ON) {
    const link = el("a", null, fbText("publicSite")); link.href = "https://cosonder.github.io/quiz/french/";
    section.append(el("p", "sub", fbText("unavailable")), link); return;
  }
  const uid = fbUid(), epoch = fbEpoch;
  section.append(el("p", "fb-note", fbText("publicNotice")));
  feedbackThreads(section, uid, epoch, false, true);
  if (!uid) { section.append(el("p", "sub", fbText("login")), fbLoginLink()); return; }
  const draftKey = "fq-feedback-draft:" + uid;
  let draft = { body: "", request: null }, sending = false;
  try { const saved = JSON.parse(localStorage.getItem(draftKey)); if (saved && typeof saved.body === "string") draft = saved; } catch (e) {}
  const input = el("textarea"); input.id = "feedbackMessage"; input.rows = 4; input.maxLength = 2000;
  input.value = draft.body; input.placeholder = fbText("input"); input.setAttribute("aria-label", fbText("input"));
  const status = el("p", "fb-note"); status.setAttribute("role", "status");
  const state = el("p", "fb-note"); state.setAttribute("role", "status");
  const send = fbButton(fbText("submit"), "btn"); send.id = "feedbackSubmit";
  const saveDraft = () => { try { localStorage.setItem(draftKey, JSON.stringify(draft)); } catch (e) {} };
  input.addEventListener("input", () => { draft = { body: input.value, request: null }; saveDraft(); });
  send.addEventListener("click", async () => {
    if (sending || !fbCurrent(uid, epoch)) return;
    const body = input.value.trim();
    if (!body || [...body].length > 2000) { status.textContent = fbText("empty"); return; }
    draft.body = input.value; draft.request ||= crypto.randomUUID(); saveDraft();
    sending = true; input.disabled = send.disabled = true; send.textContent = fbText("sending"); status.textContent = "";
    try {
      const result = await fbRpc("submit_feedback", { p_request: draft.request, p_body: body });
      if (!fbCurrent(uid, epoch)) return;
      fbSaveReward(result.reward, uid);
      draft = { body: "", request: null }; saveDraft();
      if (!section.isConnected) return;
      input.value = ""; status.textContent = fbText(result.rewarded_for_this_message ? "bonus" : "sent"); state.textContent = fbText("claimed"); refreshMine();
    } catch (e) {
      if (e.code !== "account" && section.isConnected && fbCurrent(uid, epoch)) status.textContent = fbText("messageFailed");
    } finally {
      sending = false; input.disabled = send.disabled = false; send.textContent = fbText("submit");
    }
  });
  section.append(state, input, el("span", "fb-note", fbText("limit")), send, status);
  const refreshMine=feedbackThreads(section,uid,epoch);
  fbRpc("feedback_status").then(result => {
    if (!fbCurrent(uid, epoch)) return;
    fbSaveReward(result.reward, uid);
    if (!section.isConnected) return;
    state.textContent = result.reward ? fbText("claimed") : "";
    if (result.is_admin) feedbackAdmin(section, uid, epoch);
  }).catch(e => { if (e.code !== "account" && section.isConnected && fbCurrent(uid, epoch)) state.textContent = fbText("statusFailed"); });
}

