function userAvatar(author={}) {
 const box=el('span','user-avatar');box.dataset.avatarSeed=author?.seed||'';box.setAttribute('role','img');box.setAttribute('aria-label',fbText('avatar'));
 if(author?.image && /^data:image\/jpeg;base64,\/9j\/[A-Za-z0-9+/=]+$/.test(author.image) && author.image.length<=50000){const img=el('img');img.src=author.image;img.alt='';box.append(img);}
 else if(typeof ALBUM_CARDS!=='undefined'&&ALBUM_CARDS.length){const n=parseInt(author?.seed||'0',16)||0;const c=ALBUM_CARDS[n%ALBUM_CARDS.length];box.append(albumArt(c,'avatar-postcard'));box.title=fbText('defaultAvatar')+' · '+c.city;}
 return box;
}
function avatarReplace(author){document.querySelectorAll('.user-avatar').forEach(n=>{if(n.dataset.avatarSeed===author.seed)n.replaceWith(userAvatar(author));});}
async function avatarEncode(file) {
 if(!file||!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>8*1024*1024)throw new Error('image');
 const url=URL.createObjectURL(file),img=new Image();
 try{img.src=url;await img.decode();if(!img.width||!img.height||img.width*img.height>40000000)throw new Error('image');
  const canvas=document.createElement('canvas');canvas.width=canvas.height=192;const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,192,192);
  const side=Math.min(img.width,img.height);ctx.drawImage(img,(img.width-side)/2,(img.height-side)/2,side,side,0,0,192,192);
  const data=canvas.toDataURL('image/jpeg',.82);if(data.length>50000)throw new Error('image');return data;
 }finally{URL.revokeObjectURL(url);}
}
function avatarSettings(){
 const root=el('section','card avatar-settings');root.dataset.noi18n='';root.append(el('h3',null,fbText('avatar')));
 const uid=fbUid(),epoch=fbEpoch,current=()=>root.isConnected&&fbCurrent(uid,epoch);
 if(!uid){root.append(el('p','sub',fbText('login')),fbLoginLink());return root;}
 const preview=el('div','avatar-preview'),input=el('input'),upload=fbButton(fbText('uploadAvatar')),reset=fbButton(fbText('resetAvatar')),note=el('p','fb-note');
 input.type='file';input.accept='image/jpeg,image/png,image/webp';input.hidden=true;input.setAttribute('aria-label',fbText('uploadAvatar'));note.setAttribute('role','status');let busy=false;
 const show=a=>{preview.replaceChildren(userAvatar(a));avatarReplace(a);};
 const load=()=>fbRpc('my_avatar').then(a=>{if(current()){show(a);note.textContent='';}}).catch(()=>{if(current())note.textContent=fbText('failed');});
 const save=async file=>{
  if(busy||!current())return;busy=true;upload.disabled=reset.disabled=true;note.textContent=fbText('sending');
  try{let data=null;if(file){try{data=await avatarEncode(file);}catch(e){note.textContent=fbText('avatarInvalid');return;}}
   if(!current())return;const a=await fbRpc('set_my_avatar',{p_image:data});if(current()){show(a);note.textContent=fbText('avatarSaved');}
  }catch(e){if(current())note.textContent=fbText('avatarFailed');}finally{busy=false;upload.disabled=reset.disabled=false;input.value='';}
 };
 upload.addEventListener('click',()=>input.click());input.addEventListener('change',()=>{if(input.files?.[0])save(input.files[0]);});reset.addEventListener('click',()=>save(null));
 const retry=fbButton(fbText('retry'),'fb-link');retry.addEventListener('click',load);
 root.append(preview,el('p','sub',fbText('avatarHint')),input,upload,reset,note,retry);queueMicrotask(load);return root;
}
function studyCommentCard(c){const card=el('article','fb-reply');card.append(userAvatar(c.author),el('b',null,fbText(c.is_admin?'commentAdmin':'commentUser')),el('time',null,new Date(c.created_at).toLocaleString(UI_LANG==='zh'?'zh-CN':UI_LANG)),el('p','fb-message-body',c.body));return card;}
function studyFeedback(key,picture=null,onInteract=()=>{},commentsOnly=false){
 const root=el('section','study-feedback');root.dataset.noi18n='';root.dataset.item=key;
 const mount=()=>{
  root.replaceChildren();const uid=fbUid(),epoch=fbEpoch,current=()=>root.isConnected&&fbCurrent(uid,epoch);
  const up=fbButton('','fb-vote'),down=fbButton('','fb-vote'),votes=el('div','fb-votes'),status=el('p','fb-note'),retry=fbButton(fbText('retry'),'fb-link');
  const details=el('details','study-discussion'),summary=el('summary'),list=el('div','fb-comments'),more=fbButton(fbText('more')),note=el('p','fb-note');
  let data=null,voteBusy=false,desired=null,after=0,commentsBusy=false,loaded=false;retry.hidden=true;more.hidden=true;status.setAttribute('role','status');note.setAttribute('role','status');
  const draw=()=>{up.textContent='👍 '+fbText('like')+' '+(data?data.likes:'—');down.textContent='😞 '+fbText('dislike')+(data&&Object.hasOwn(data,'dislikes')?' '+data.dislikes:'');for(const [b,v]of [[up,1],[down,-1]]){b.disabled=voteBusy||!data;b.setAttribute('aria-pressed',String(data?.mine===v));}summary.textContent=fbText('studyComments')+' '+(data?data.comments:'—');};
  const update=d=>{data=d;studyCounts.set(key,{likes:d.likes,comments:d.comments});if(picture)studyCounts.set('p:'+picture,{likes:d.likes,comments:0});draw();};
  const load=async()=>{retry.hidden=true;status.textContent=fbText('loading');try{const [d,p]=await Promise.all([fbRpc('study_feedback',{p_item:key},true),picture?fbRpc('picture_feedback',{p_picture:picture},true):Promise.resolve(null)]);if(current()){update(p?{...d,...p}:d);status.textContent='';}}catch(e){if(current()){status.textContent=fbText('failed');retry.hidden=false;}}};
  const vote=async target=>{
   if(voteBusy||!current())return;onInteract();if(!uid){status.replaceChildren(document.createTextNode(fbText('login')+' · '),fbLoginLink());return;}
   voteBusy=true;desired=target;retry.hidden=true;draw();
   try{const d=await fbRpc(picture?'set_picture_feedback':'set_study_vote',picture?{p_picture:picture,p_vote:target}:{p_item:key,p_vote:target});if(current()){update({...data,...d});desired=null;status.textContent=fbText(target?'saved':'removed');}}
   catch(e){if(current()){status.textContent=fbText('saveFailed');retry.hidden=false;}}finally{voteBusy=false;if(current())draw();}
  };
  const loadComments=async reset=>{
   if(commentsBusy||!current())return;commentsBusy=true;more.disabled=true;note.textContent=fbText('loading');
   try{const d=await fbRpc('study_comments_page',{p_item:key,p_after:reset?0:after},true);if(!current())return;if(reset){list.replaceChildren();after=0;}
    d.comments.forEach(c=>{list.append(studyCommentCard(c));after=c.id;});loaded=true;more.hidden=!d.has_more;if(data)update({...data,comments:d.total});note.textContent=d.total?'':fbText('commentNone');
   }catch(e){if(current()){note.textContent=fbText('failed');more.hidden=false;}}finally{commentsBusy=false;more.disabled=false;}
  };
  up.addEventListener('click',()=>vote(data?.mine===1?0:1));down.addEventListener('click',()=>vote(data?.mine===-1?0:-1));retry.addEventListener('click',()=>desired===null?load():vote(desired));
  summary.addEventListener('click',onInteract);details.addEventListener('toggle',()=>{if(details.open){onInteract();if(!loaded)loadComments(true);}});more.addEventListener('click',()=>loadComments(!loaded));
  details.append(summary,list,more,note);
  if(uid){const input=el('textarea'),send=fbButton(fbText('commentSend'),'btn'),msg=el('p','fb-note');input.rows=3;input.maxLength=2000;input.placeholder=fbText('commentInput');input.setAttribute('aria-label',fbText('commentInput'));msg.setAttribute('role','status');let request=null,sending=false;
   input.addEventListener('input',()=>{request=null;});input.addEventListener('focus',onInteract);
   send.addEventListener('click',async()=>{onInteract();if(sending||!current())return;const body=input.value.trim();if(!body||[...body].length>2000){msg.textContent=fbText('empty');return;}
    request ||= crypto.randomUUID();sending=true;send.disabled=input.disabled=true;msg.textContent=fbText('sending');
    try{const c=await fbRpc('comment_study',{p_item:key,p_request:request,p_body:body});if(!current())return;request=null;input.value='';msg.textContent=fbText('commentSent');msg.append(studyCommentCard(c));await loadComments(true);}
    catch(e){if(current())msg.textContent=fbText('commentFailed');}finally{sending=false;send.disabled=input.disabled=false;}
   });details.append(input,send,msg);
  }else details.append(el('p','fb-note',fbText('commentLogin')),fbLoginLink());
  votes.append(up,down);if(!commentsOnly)root.append(votes);root.append(status,retry,details);draw();queueMicrotask(load);
 };
 fbPictures.forEach(x=>{if(!x.root.isConnected)fbPictures.delete(x);});fbPictures.add({root,reload:mount});mount();return root;
}
