let studyCounts=new Map(),studySort={q:'normal',w:'normal'},studyStatsRun=0;
async function studyLoadStats(){
 const result=new Map();let after='';
 for(;;){const page=await fbRpc('study_stats',{p_after:after},true);for(const r of page)result.set(r.item_key,r);if(page.length<1000)break;const next=page[page.length-1].item_key;if(next===after)throw new Error('cursor');after=next;}
 return result;
}
function studyWordKey(w){return /^n/.test(w.pos||'')?w.fr.replace(/^(?:(?:de la|de l[’']|le|la|les|un|une|des|du)\s+|l[’'])/i,''):w.fr;}
function studySorted(items,kind){
 const mode=studySort[kind];if(!mode||mode==='normal')return items;
 const metric=x=>{const key=kind+':'+x.id;return Number(studyCounts.get(kind==='w'&&mode==='likes'&&vPic(x)?'p:'+vPic(x):key)?.[mode]||0);};
 return items.slice().sort((a,b)=>mode==='alphabet'?studyWordKey(a).localeCompare(studyWordKey(b),'fr',{sensitivity:'base'})||String(a.id).localeCompare(String(b.id)):metric(b)-metric(a)||String(a.id).localeCompare(String(b.id),'fr'));
}
function studySortQuestions(qs,key){return /^(tag:|wrong:|listen:|mistakes:|ch:|ep:|fr-)/.test(key)?studySorted(qs,'q'):qs;}
function studySortControl(kind,onChange=()=>{}){
 const row=el('div','study-sort');row.dataset.noi18n='';const lab=el('label'),select=el('select'),note=el('span','fb-note'),refresh=fbButton(fbText('sortRefresh'),'fb-link');
 lab.append(el('span',null,fbText('resultSort')),select);select.setAttribute('aria-label',fbText('resultSort'));note.setAttribute('role','status');
 for(const [value,text]of [['normal','normal'],['likes','liked'],['comments','discussed'],...(kind==='w'?[['alphabet','alphabet']]:[])]){const o=el('option',null,fbText(text));o.value=value;select.append(o);}select.value=studySort[kind];
 const change=async()=>{const mode=select.value,run=++studyStatsRun,uid=fbUid(),epoch=fbEpoch;select.disabled=refresh.disabled=true;note.textContent=fbText('loading');
  try{const counts=['likes','comments'].includes(mode)?await studyLoadStats():null;if(run!==studyStatsRun||!row.isConnected||!fbCurrent(uid,epoch))return;if(counts)studyCounts=counts;studySort[kind]=mode;note.textContent='';onChange();}
  catch(e){if(row.isConnected){select.value=studySort[kind];note.textContent=fbText('sortFailed');}}finally{select.disabled=refresh.disabled=false;}
 };select.addEventListener('change',change);refresh.addEventListener('click',change);row.append(lab,refresh,note,el('small',null,fbText('sortHint')));return row;
}

