// 某个页面能看到的记录：去掉别的页面专属的条目，空了的版本不显示
function changelogFor(page) {
  return CHANGELOG.map(x => ({ v: x.v, d: x.d, items: (!x.p || x.p === page) ? x.items.map(it => typeof it === "string" ? it : (!it.p || it.p === page) ? it.t : null).filter(Boolean) : [] }))
    .filter(x => x.items.length);
}
// 设置页最下面的“版本”卡片
function changelogCard(wrap, page) {
  const list = changelogFor(page), now = list[0];
  const card = setSection(wrap, "版本", `当前版本 v${now.v} · ${now.d} 更新`);
  card.classList.add("cl-card");
  const d = el("details", "cl-fold");
  const s = el("summary", null, `查看更新记录（共 ${list.length} 个版本）`);
  d.append(s);
  list.forEach((x, index) => {
    const box = el("div", "cl-ver");
    const h = el("div", "cl-head"); h.append(el("b", null, "v" + x.v), el("span", "cl-date", x.d));
    const ul = el("ul");
    const french = typeof UI_LANG !== "undefined" && UI_LANG === "fr";
    if (french && index >= 10) { ul.dataset.noi18n = ""; ul.dataset.i18nArchive = ""; }
    x.items.forEach(t => ul.append(el("li", null, french && index < 10 ? tr(t) : t)));
    box.append(h, ul); d.append(box);
  });
  card.append(d);
  return card;
}

// ---------- 做题记录的公共定义（账号同步用） ----------
// 记录分四类：答题、模拟卷、单词、金币和道具；每条记录按内容（键排序后）算指纹去重
const REC_COLLS = ["answers", "exams", "vocab", "game"];
const REC_APP = (BANK[0] && BANK[0].id.split("-")[0]) || "quiz";   // fr 法语页 / sc 随机分析页
const recKey = d => JSON.stringify(Object.keys(d).sort().map(k => [k, d[k]]));
// 日历文件每行不超过 75 字节，长行折行（续行以空格开头），不拆开多字节字符
function foldIcs(line) {
  const enc = new TextEncoder(), out = [];
  let cur = "", lim = 75;
  for (const ch of line) {
    if (enc.encode(cur + ch).length > lim) { out.push(cur); cur = " "; lim = 75; }
    cur += ch;
  }
  out.push(cur);
  return out.join("\r\n");
}
// ---------- 每日提醒：生成一个每天重复、带闹钟的日历事件（.ics），加到系统日历里 ----------
function remindRow() {
  const row = el("div", "heat-remind");
  const local = typeof claude === "undefined";
  if (!local) {
    row.append(document.createTextNode("每日提醒：在 "));
    const a = el("a", null, "公开网站的学习进度页"); a.href = "https://cosonder.github.io/quiz/"; a.target = "_blank"; a.rel = "noopener";
    row.append(a, document.createTextNode(" 下载日历提醒，加到 iPad / 手机日历后每天到点通知。"));
    return row;
  }
  let t = "20:00";
  try { t = localStorage.getItem("quiz-remind") || t; } catch (e) {}
  const lab = el("label", null, "每日提醒 ");
  const inp = el("input"); inp.type = "time"; inp.value = t; inp.id = "remindTime";
  lab.append(inp);
  const btn = el("button", "btn ghost", "加到日历"); btn.type = "button"; btn.id = "remindBtn";
  const note = el("span", null, "下载一个每天重复的日历事件，打开后加到系统日历，到点会通知。");
  btn.addEventListener("click", () => {
    const [hh, mm] = (inp.value || "20:00").split(":");
    try { localStorage.setItem("quiz-remind", `${hh}:${mm}`); } catch (e) {}
    const now = new Date(), p2 = n => String(n).padStart(2, "0");
    const stamp = now.toISOString().replace(/[-:]/g, "").replace(/\.\d+/, "");
    const url = location.href.split("#")[0];
    const ics = ["BEGIN:VCALENDAR", "VERSION:2.0", "PRODID:-//quiz//daily reminder//ZH", "CALSCALE:GREGORIAN", "BEGIN:VEVENT",
      `UID:quiz-daily-${stamp}@cosonder.github.io`, `DTSTAMP:${stamp}`,
      `DTSTART:${now.getFullYear()}${p2(now.getMonth() + 1)}${p2(now.getDate())}T${hh}${mm}00`, "DURATION:PT20M", "RRULE:FREQ=DAILY",
      "SUMMARY:做题时间", `DESCRIPTION:打开练习页做几道题：${url}`, `URL:${url}`,
      "BEGIN:VALARM", "ACTION:DISPLAY", "DESCRIPTION:做题时间", "TRIGGER:PT0M", "END:VALARM",
      "END:VEVENT", "END:VCALENDAR"].map(foldIcs).join("\r\n") + "\r\n";
    const a = document.createElement("a");
    a.href = URL.createObjectURL(new Blob([ics], { type: "text/calendar" }));
    a.download = "daily-quiz-reminder.ics";
    document.body.append(a); a.click(); a.remove();
    note.textContent = `已生成每天 ${hh}:${mm} 的提醒，打开下载的文件并选择“添加到日历”。`;
  });
  row.append(lab, btn, note);
  return row;
}
// ---------- 标签检索：勾选标签 → 检索出题目；错题本按标签筛选 ----------
const tagSaved = (() => { try { return JSON.parse(localStorage.getItem("fq-tags") || "{}"); } catch (e) { return {}; } })();
let pickTags = new Set(tagSaved.tags || []);
let tagMode = tagSaved.mode === "all" ? "all" : "any";
let tagRandom = !!tagSaved.rand;   // “随机”：打乱检索结果的顺序   // any：带任一所选标签；all：同时带所有所选标签
const saveTags = () => { try { localStorage.setItem("fq-tags", JSON.stringify({ tags: [...pickTags], mode: tagMode, rand: tagRandom })); } catch (e) {} };
const ATTEMPT_TAGS = ["未做过", "已做过"];
let attemptCache = { raw: null, length: -1, ids: new Set() };
function attemptedIds() {
  const raw = typeof ansRaw !== "undefined" && ansRaw ? ansRaw : bookCache?.raw || [];
  if (attemptCache.raw !== raw || attemptCache.length !== raw.length) attemptCache = {raw, length: raw.length, ids: new Set(raw.map(d => d.qid))};
  return attemptCache.ids;
}
function attemptMatch(id, states = []) {
  return !states.length || states.length === 2 || states.includes(attemptedIds().has(id) ? "已做过" : "未做过");
}
function tagMatch(q, tags, mode) {
  if (!q || !tags.length) return false;
  const states = tags.filter(t => ATTEMPT_TAGS.includes(t));
  if (!attemptMatch(q.id, states)) return false;
  const lv = tags.filter(t => LEVELS.includes(t)), tp = tags.filter(t => !LEVELS.includes(t) && !ATTEMPT_TAGS.includes(t));
  const matches = t => q.level === t || (q.tags || []).includes(t);
  const group = a => !a.length || (mode === "all" ? a.every(matches) : a.some(matches));
  return group(lv) && group(tp);
}
const tagKey = (kind, tags = [...pickTags], mode = tagMode, rnd = tagRandom) => `${kind}:${mode}${rnd ? "!" : ""}:${tags.join("|")}`;
function parseTagKey(key) {
  const m = /^(tag|wrong):(any|all)(!?):(.*)$/.exec(key);
  return m ? { kind: m[1], mode: m[2], rnd: m[3] === "!", tags: m[4] ? m[4].split("|") : [] } : null;
}
function wrongIds() {
  if (bookCache?.wrong) return new Set(bookCache.wrong.map(d => d.qid));
  const latest = new Map();
  if (typeof ansRaw !== "undefined") [...(ansRaw || [])].sort((a,b)=>String(a.at).localeCompare(String(b.at))).forEach(d=>latest.set(d.qid,d));
  return new Set([...latest.values()].filter(d=>!d.isCorrect).map(d=>d.qid));
}
function tagResults(pool, tags, mode, random, kind) {
  const list = pool.filter(q => !tags.length ? kind === "wrong" || random : tagMatch(q, tags, mode));
  return typeof qlApply === "function" ? qlApply(list, tagKey(kind, tags, mode, random)) : list;
}
function tagToggle(tags, t) { return tags.includes(t) ? tags.filter(x => x !== t) : tags.concat(t); }
function tagLabel(p) {
  const lv = p.tags.filter(t => LEVELS.includes(t)).sort((a, b) => LEVELS.indexOf(a) - LEVELS.indexOf(b)), tp = p.tags.filter(t => !LEVELS.includes(t));
  const t = (lv.length ? lv.join(p.mode === "all" ? " + " : " / ") + (tp.length ? " · " : "") : "") + (tp.length ? tp.join(p.mode === "all" ? " + " : " / ") : lv.length ? "" : "全部");
  return (p.kind === "wrong" ? "错题 · " : "标签 · ") + (p.rnd ? "随机 · " : "") + t + (tp.length > 1 || lv.length > 1 ? (p.mode === "all" ? "（同时满足）" : "（任一）") : "");
}

function tagPanel() {
  const quiz = view === "quiz";
  const box = el("div", "tag-panel");
  // 题目池：答题页是全部题，错题本是当前错题
  const wids = quiz ? null : wrongIds();
  const pool = quiz ? BANK : BANK.filter(q => wids.has(q.id));
  const sum = el("div", "tag-sum");
  const mode = el("div", "tag-mode");
  const act = el("div", "tag-act");
  const go = el("button", "btn", quiz ? "检索并开始做题" : "检索错题");
  go.type = "button"; go.id = "tagGo";
  const clear = el("button", "btn ghost", "清空");
  clear.type = "button";
  const chips = [];
  const randChip = el("button", "chip"); randChip.type = "button"; randChip.id = "randChip";
  randChip.append(document.createTextNode("随机"), el("small", null, "打乱顺序"));
  randChip.addEventListener("click", () => { tagRandom = !tagRandom; selectionChanged(); });
  const selectionChanged = () => {
    if (quiz && typeof queueQuizTags === "function") queueQuizTags();
    saveTags(); refresh();
    if (!quiz) { bookFilter = pickTags.size || tagRandom ? tagKey("wrong") : "all"; drawBook(); }
    if (typeof planRefresh === "function") planRefresh();
  };
  const refresh = () => {
    const tags = [...pickTags];
    const n = tagResults(pool, tags, tagMode, tagRandom, quiz ? "tag" : "wrong").length;
    sum.textContent = "";
    if (!tags.length && !tagRandom) sum.append(document.createTextNode(quiz ? "勾选标签来检索题目（可多选）" : "勾选标签来筛选错题（可多选）"));
    else { sum.append(document.createTextNode(tags.length ? `已选 ${tags.length} 个标签 · ${quiz ? "共" : "错题"} ` : (quiz ? "全部题目 · 共 " : "全部错题 · 共 ")), el("b", null, String(n)), document.createTextNode(" 题" + (tagRandom ? " · 随机顺序" : ""))); }
    if (quiz && typeof pendingQuizTagKey !== "undefined" && pendingQuizTagKey) {
      sum.append(el("p", "sub", "标签已更改：点击“下一组”会自动应用；当前这一组保持不变。也可点击“检索并开始做题”立即开始。"));
    }
    go.disabled = !n;
    clear.disabled = !tags.length && !tagRandom;
    randChip.setAttribute("aria-pressed", String(tagRandom));
    chips.forEach(c => {
      c.setAttribute("aria-pressed", String(pickTags.has(c.dataset.tag)));
      const n = tagResults(pool, tagToggle(tags, c.dataset.tag), tagMode, tagRandom, quiz ? "tag" : "wrong").length;
      c.querySelector("small").textContent = String(n);
      c.disabled = false;
    });
  };
  [["any", "任一标签（或）"], ["all", "同时满足（与）"]].forEach(([m, t]) => {
    const b = el("button", null, t); b.type = "button";
    b.setAttribute("aria-pressed", String(tagMode === m));
    b.addEventListener("click", () => { tagMode = m; mode.querySelectorAll("button").forEach(x => x.setAttribute("aria-pressed", String(x === b))); selectionChanged(); });
    mode.append(b);
  });
  go.addEventListener("click", () => {
    if (quiz) { startSet(tagKey("tag"), true); }
    else { bookFilter = tagKey("wrong"); renderToc(); drawBook(); }
    afterPick();
  });
  clear.addEventListener("click", () => { pickTags.clear(); tagRandom = false; selectionChanged(); });
  act.append(go, clear);
  if(typeof studySortControl === "function")box.append(studySortControl("q",()=>{if(quiz){if(pickTags.size||tagRandom)startSet(tagKey("tag"),true);else if(set)startSet(set.key,true);}else drawBook();}));
  box.append(sum, mode, act, el("p", "sub", "标签旁数字表示点击该标签后预计匹配的总题数；点击已选标签会取消选择。"));
  const rg = el("div", "tag-group"), rw = el("div", "chips");
  rg.append(el("div", "tag-gname", "出题方式"), rw); rw.append(randChip);
  ATTEMPT_TAGS.forEach(t => {
    const c = el("button", "chip"); c.type="button"; c.dataset.tag=t;
    c.append(document.createTextNode(t),el("small"));
    c.addEventListener("click",()=>{pickTags.has(t)?pickTags.delete(t):pickTags.add(t);selectionChanged();});
    chips.push(c);rw.append(c);
  });box.append(rg);
  TAG_GROUPS.forEach(g => {
    const grp = el("div", "tag-group");
    grp.append(el("div", "tag-gname", g.g));
    if (g.g === "难度") grp.append(el("div", "lv-note", "难度标签也遵守或／与；难度范围与内容标签同时满足。未做过／已做过单独限定作答状态，两项都选表示不限。"));
    const wrap = el("div", "chips");
    g.tags.forEach(t => {
      const n = pool.reduce((s, q) => s + (q.tags.includes(t) ? 1 : 0), 0);
      const c = el("button", "chip");
      c.type = "button"; c.dataset.tag = t;
      c.append(document.createTextNode(t), el("small", null, String(n)));
      c.disabled = !n && !pickTags.has(t);
      c.addEventListener("click", () => { pickTags.has(t) ? pickTags.delete(t) : pickTags.add(t); selectionChanged(); });
      chips.push(c);
      wrap.append(c);
    });
    grp.append(wrap);
    box.append(grp);
  });
  refresh();
  return box;
}

// 错题本：每个标签累计答错多少次（所有答错记录，含后来改对的）、目前还有几道错题；按答错次数从多到少
function tagDistCard() {
  const card = el("section", "card dist");
  card.append(el("h3", null, "错题分布（按标签）"));
  const times = new Map(), now = new Map(), wids = wrongIds();
  (bookCache?.raw || []).forEach(d => { if (d.isCorrect) return; const q = BY_ID.get(d.qid); if (q) q.tags.forEach(t => times.set(t, (times.get(t) || 0) + 1)); });
  BANK.forEach(q => { if (wids.has(q.id)) q.tags.forEach(t => now.set(t, (now.get(t) || 0) + 1)); });
  const rows = [...times.entries()].sort((a, b) => b[1] - a[1] || (now.get(b[0]) || 0) - (now.get(a[0]) || 0));
  if (!rows.length) { card.append(el("p", "empty", "还没有答错过的题。")); return card; }
  card.append(el("p", "sub", "条长 = 累计答错次数；点一行只看这个标签的错题。"));
  const max = rows[0][1], list = el("div", "dist");
  const show = n => {
    list.textContent = "";
    rows.slice(0, n).forEach(([t, c]) => {
      const r = el("button", "dist-row"); r.type = "button";
      const p = parseTagKey(bookFilter);
      r.setAttribute("aria-pressed", String(!!p && p.tags.length === 1 && p.tags[0] === t));
      const bar = el("span", "bar2"), fill = el("i"); fill.style.width = (c / max * 100) + "%"; bar.append(fill);
      const num = el("span", "n"); num.append(el("b", null, `${c} 次`), document.createTextNode(` · 现有 ${now.get(t) || 0} 题`));
      r.append(el("span", null, t), bar, num);
      r.addEventListener("click", () => { const tags = LEVELS.includes(t) ? [t] : [...pickTags].filter(x => LEVELS.includes(x)).concat(t); pickTags = new Set(tags); saveTags(); bookFilter = tagKey("wrong", tags, "any"); renderToc(); drawBook(); });
      list.append(r);
    });
  };
  show(12);
  card.append(list);
  if (rows.length > 12) {
    const more = el("button", "btn ghost dist-more", `显示全部 ${rows.length} 个标签`); more.type = "button";
    more.addEventListener("click", () => { show(rows.length); more.remove(); });
    card.append(more);
  }
  return card;
}
// ---------- 目录 ----------
function tocItem({ no, title, zh, badge, badgeCls, current, disabled, onClick }) {
  const li = el("li");
  const b = el("button", "item");
  b.type = "button";
  if (current) b.setAttribute("aria-current", "true");
  b.disabled = !!disabled;
  b.append(el("span", "no", no ?? ""));
  const t = el("span", null, title);
  if (zh) t.append(el("span", "zh", zh));
  b.append(t, el("span", "badge " + (badgeCls || ""), badge));
  b.addEventListener("click", onClick);
  li.append(b);
  return li;
}
function groupEntry(key, { no, title, zh }) {
  const quiz = view === "quiz";
  const c = quiz ? qlApply(members(key), key).length : (bookCache ? bookCache.wrong.filter(d => inGroup(key, BY_ID.get(d.qid)) && practiceAllows(BY_ID.get(d.qid), mistakeKey(key))).length : 0);
  return tocItem({
    no, title, zh,
    badge: quiz ? (c ? `${c} 题` : "—") : (c ? `${c} 错` : "—"),
    badgeCls: c ? (quiz ? "" : "bad") : "zero",
    current: quiz ? set?.key === key : bookFilter === key,
    disabled: !c,
    onClick: () => { if (quiz) startSet(key); else { bookFilter = key; renderToc(); drawBook(); } afterPick(); },
  });
}
function folder(title, sub, keys, build) {
  const d = el("details");
  const sum = el("summary");
  sum.append(el("span", "pt", title), el("span", "pg", sub || ""));
  d.append(sum);
  const ul = el("ul");
  keys.forEach(k => ul.append(build(k)));
  d.append(ul);
  const quiz = view === "quiz";
  d.open = keys.some(k => (quiz ? set?.key === k : bookFilter === k))
    || (!quiz && bookCache && keys.some(k => bookCache.wrong.some(x => inGroup(k, BY_ID.get(x.qid)))));
  return d;
}

// 三个大栏（按标签 / 按书籍 / 零基础与听力）可以折叠；用户手动开合后记住，直到刷新页面
const tocFold = {};
function tocSection(id, title, sub, autoOpen) {
  const d = el("details", "legacy toc-fold"), s = el("summary");
  s.append(el("span", null, title));
  if (sub) s.append(el("span", "toc-fold-sub", sub));
  d.append(s);
  d.open = id in tocFold ? tocFold[id] : !!autoOpen;
  d.addEventListener("toggle", () => { tocFold[id] = d.open; });
  return d;
}
// 把几个子文件夹装进一个大文件夹（某个子文件夹展开时大文件夹也展开）
function bookFolder(title, sub, subs) {
  const top = folder(title, sub, [], null), box = top.querySelector("ul");
  subs.forEach(f => { const li = el("li"); li.append(f); box.append(li); if (f.open) top.open = true; });
  return top;
}
// 听力文件夹（含废柴联盟子文件夹）
function listenFolder() {
 return {listen:listeningPanel(view!=="quiz"),keys:["listen:"]};
}
function renderToc() {
  if (typeof navSync === "function") navSync();
  toc.innerHTML = "";
  const quiz = view === "quiz";
  if (quiz) toc.append(planTocItem());   // 学习进度页有完整的计划卡，这里不重复
  const cur = quiz ? set?.key : bookFilter;
  const isTag = !!cur && !!parseTagKey(cur);

  // 听力板块：只有听力题
  if (quiz && typeof qBoard !== "undefined" && qBoard === "listen") {
    toc.append(el("div", "toc-sec", "听力"), listenFolder().listen);
    return;
  }

  // 按标签选择
  const tagSec = tocSection("tags", "按标签选择", pickTags.size ? `已选 ${pickTags.size} 个` : "", isTag);
  tagSec.append(tagPanel());
  toc.append(tagSec);

  // 按书籍选择：三本书各是一个文件夹，里面保留各自原来的分组
  const books = [];
  const afg = bookFolder("Advanced French Grammar · Monique L'Huillier", "按章节", PARTS.map(pt => {
    const keys = pt.chs.map(([n]) => "ch:" + n);
    return folder(`${pt.n} ${pt.t}`, `p.${pt.p}`, keys, k => {
      const c = CH.get(Number(k.slice(3)));
      return groupEntry(k, { no: String(c.n), title: c.t, zh: UI_LANG !== "zh" ? `p.${c.p}` : `${c.zh} · p.${c.p}` });
    });
  }));
  books.push(afg);
  if (quiz && typeof GPA1 !== "undefined" && GPA1.length) {
    const parts = [[1, 9], [10, 20], [21, 27], [28, 34], [35, 42], [43, 49], [50, 54], [55, 60]];
    books.push(bookFolder("Grammaire progressive du français · A1", `${GPA1.length} 个单元 · 每单元 10 题`, parts.map(([a, b], i) => {
      const keys = GPA1.filter(u => u.unit >= a && u.unit <= b).map(u => "fr-ga" + u.unit);
      return keys.length ? folder(`第 ${i + 1} 部分`, `第 ${a}–${b} 单元`, keys, k => { const u = GPA1.find(x => "fr-ga" + x.unit === k); return groupEntry(k, UI_LANG !== "zh" ? { no: String(u.unit), title: u.title } : { no: String(u.unit), title: u.zh, zh: u.title }); }) : null;
    }).filter(Boolean)));
  }
  if (quiz && typeof GPA2 !== "undefined" && GPA2.length) {
    const chaps = [...new Set(GPA2.map(u => u.chap))];
    books.push(bookFolder("Grammaire progressive du français · A2–B1", `${chaps.length} 章 · ${GPA2.length} 个小节`, chaps.map(c => {
      const us = GPA2.filter(u => u.chap === c), keys = us.map(u => "fr-gb" + u.unit.replace(".", "s"));
      return folder(`${c} · ${us[0].chapTitle}`, `${us.length} 个小节`, keys, k => { const u = us.find(x => "fr-gb" + x.unit.replace(".", "s") === k); return groupEntry(k, UI_LANG !== "zh" ? { no: u.unit, title: u.title, zh: u.lv } : { no: u.unit, title: u.zh, zh: `${u.title} · ${u.lv}` }); });
    })));
  }
  const bookSec = tocSection("books", "按书籍选择", `${books.length} 本书`, books.some(b => b.open));
  const bul = el("ul", "toc-books");
  books.forEach(b => { const li = el("li"); li.append(b); bul.append(li); });
  bookSec.append(bul);

  if (!quiz) {
    // 错题本：“全部错题”放在最前面
    const total = bookCache ? bookCache.wrong.filter(d => practiceAllows(BY_ID.get(d.qid), mistakeKey("all"))).length : 0;
    const ul = el("ul");
    ul.append(tocItem({ title: "全部错题", badge: bookCache ? `${total}` : "…", badgeCls: total ? "bad" : "zero",
      current: bookFilter === "all", onClick: () => { bookFilter = "all"; renderToc(); drawBook(); afterPick(); } }));
    toc.append(ul);
  }
  toc.append(bookSec);

  if (quiz) {
    // 语法板块：最后是零基础入门
    toc.append(el("div", "toc-sec", "零基础"));
    const ul = el("ul");
    ul.append(groupEntry("fr-r0", { title: "零基础入门", zh: "数字、星期、月份、问候与礼貌用语" }));
    toc.append(ul);
    return;
  }
  // 错题本：听力错题放在可折叠的栏里
  const { listen, keys } = listenFolder();
  const otherSec = tocSection("other", "听力", "", !!cur && keys.includes(cur));
  otherSec.append(listen);
  toc.append(otherSec);
}

// 学习进度展板“按书籍章节”用：每本书一组，每行一章（或一个单元），行里是这一章的题组键
function progBookGroups() {
  const EN = UI_LANG !== "zh", out = [];
  out.push({ g: "零基础", rows: [["零基础入门", ["fr-r0"]]] });
  out.push({ g: "Advanced French Grammar", rows: PARTS.flatMap(pt => pt.chs.map(([n]) => { const c = CH.get(n); return [`${n} · ${c.t}`, ["ch:" + n]]; })) });
  if (typeof GPA1 !== "undefined" && GPA1.length) out.push({ g: "Grammaire progressive · A1", rows: GPA1.map(u => [`${u.unit} · ${EN ? u.title : u.zh}`, ["fr-ga" + u.unit]]) });
  if (typeof GPA2 !== "undefined" && GPA2.length) {
    const chaps = [...new Set(GPA2.map(u => u.chap))];
    out.push({ g: "Grammaire progressive · A2–B1", rows: chaps.map(c => { const us = GPA2.filter(u => u.chap === c); return [`${c} · ${us[0].chapTitle}`, us.map(u => "fr-gb" + u.unit.replace(".", "s"))]; }) });
  }
  out.push({ g: "听力", rows: ROUNDS.filter(r => r.kind === "listen").map(r => [r.name.split(" · ").reverse()[0], [r.id]]).concat([["废柴联盟", ["fr-r13"]]]) });
  return out;
}

// 学习进度页：错题的筛选目录（标签、全部错题、书籍章节、听力）放在错题本卡片里，折叠起来
function tocInBook(card) {
  const d = el("details", "book-toc");
  d.append(el("summary", null, "筛选错题：按标签 / 书籍章节"));
  try { d.open = localStorage.getItem("fq-booktoc") === "1" || bookFilter !== "all"; } catch (e) { d.open = bookFilter !== "all"; }
  d.addEventListener("toggle", () => { try { localStorage.setItem("fq-booktoc", d.open ? "1" : "0"); } catch (e) {} });
  d.append(toc);
  card.append(d);
}

// ---------- 答题的难度等级（设置里选）：零基础 / A1–C2 / 关闭 ----------
// 选某一档时，每个题组按下面的比例从各等级的题里抽（零基础只出零基础题；关闭时出全部题）。
// 只影响普通语法题组；零基础入口与听力标签检索使用各自的难度，不叠加全局过滤。计划与复习严格遵守所选难度，游戏不受影响。
const QL_OPTS = [["zero", "零基础"], ["A1", "A1"], ["A2", "A2"], ["B1", "B1"], ["B2", "B2"], ["C1", "C1"], ["C2", "C2"], ["off", "关闭难度等级"]];
const QL_MIX = {
  zero: { "零基础": 1 },
  A1: { A1: 9, A2: 1 },
  A2: { A1: .5, A2: 9, B1: .5 },
  B1: { A2: .5, B1: 9, B2: .5 },
  B2: { B1: .5, B2: 9, C1: .5 },
  C1: { B2: .5, C1: 9, C2: .5 },
  C2: { C1: 1, C2: 9 },
  off: null,
};
let qLevel = (() => { try { const v = localStorage.getItem("fq-qlevel"); return QL_MIX.hasOwnProperty(v) ? v : "off"; } catch (e) { return "off"; } })();
const qlName = k => (QL_OPTS.find(x => x[0] === k) || [k, k])[1];
function qlMixText(k) {
  const m = QL_MIX[k];
  if (!m) return "出题库里所有难度的题。";
  const tot = Object.values(m).reduce((a, b) => a + b, 0);
  return k === "zero" ? "只出“零基础”的题（数字、星期、月份、问候、自我介绍、礼貌用语）。" : "出题比例：" + Object.entries(m).map(([l, w]) => `${l} ${Math.round(w / tot * 100)}%`).join(" · ") + "。";
}
// 固定种子的随机数：同一个题组、同一档难度，每次排出来的题一样（这样“做到第几题”还对得上）
function qlRng(str) { let h = 2166136261; for (const c of str) { h ^= c.charCodeAt(0); h = Math.imul(h, 16777619); } return () => { h += 0x6D2B79F5; let t = h; t = Math.imul(t ^ t >>> 15, t | 1); t ^= t + Math.imul(t ^ t >>> 7, t | 61); return ((t ^ t >>> 14) >>> 0) / 4294967296; }; }
// Explicit directory levels take priority; plan/review never mix adjacent levels.
function practiceLevels(key = "") {
  if (key.startsWith("mistakes:")) key = mistakeFilter(key).scope;
  let explicit = [], specified = false;
  if (key.startsWith("listen:")) explicit = listeningFilter(key).levels;
  else {
    const p = parseTagKey(key);
    if (p) { explicit = p.tags.filter(t => LEVELS.includes(t)); specified = true; }
    else if (/^(rev|learn):/.test(key)) explicit = key.slice(key.indexOf(":") + 1).split("|").filter(t => LEVELS.includes(t));
  }
  if (explicit.length) return [...new Set(explicit)].sort();
  if (!specified) { try { const selected = [...pickTags].filter(t => LEVELS.includes(t)); if (selected.length) return selected.sort(); } catch (e) {} }
  // planRefresh also runs during initial script loading, before settings initialize.
  try { return qLevel === "off" ? [] : [qLevel === "zero" ? "零基础" : qLevel]; } catch (e) { return []; }
}
function practiceLevelMode(key = "") {
  if(key.startsWith("mistakes:")) key=mistakeFilter(key).scope;
  const p=parseTagKey(key);if(p) return p.mode;
  if(key.startsWith("listen:")) return "any";
  try { return tagMode; } catch(e) { return "any"; }
}
function practiceAllows(q, key = "") {
  const levels = practiceLevels(key), has = t => q.level===t || (q.tags||[]).includes(t);
  return !!q && (!levels.length || (practiceLevelMode(key)==="all" ? levels.every(has) : levels.some(has)));
}
function practiceScopeKey(key = "") { const levels=practiceLevels(key);return levels.length ? practiceLevelMode(key)+":"+levels.join("|") : ""; }
function practiceScopeNote(key = "") { return tr("计划与复习难度：") + (practiceLevels(key).join(practiceLevelMode(key)==="all" ? " ∧ " : " ∨ ") || tr("全部")) + tr("。优先使用目录所选难度，未选择时使用设置中的难度。"); }
function qlApply(list, key) {
  if (/^(rev|learn|plan|wrong|mistakes):/.test(key)) return list.filter(q => practiceAllows(q, key));
  const selected = parseTagKey(key);
  if (selected && selected.tags.some(t => LEVELS.includes(t))) return list;
  const mix = QL_MIX[qLevel];
  if (!mix || key === "fr-r0" || /^(rev|learn|plan|tour|listen):/.test(key)) return list;
  const pools = {}; Object.keys(mix).forEach(l => { pools[l] = list.filter(q => q.level === l); });
  const have = Object.keys(mix).filter(l => pools[l].length);
  if (!have.length) return [];
  // 按比例定每个等级出几道：总数取到“某个等级的题用完”为止，这样比例不走样
  const W = have.reduce((a, l) => a + mix[l], 0);
  const N = Math.min(...have.map(l => pools[l].length * W / mix[l]));
  const want = {}; have.forEach(l => { want[l] = Math.max(1, Math.round(N * mix[l] / W)); want[l] = Math.min(want[l], pools[l].length); });
  // 按权重交错排开（同一等级里保持题组原来的顺序）
  const rnd = qlRng(key + "|" + qLevel), out = [], used = {}; have.forEach(l => { used[l] = 0; });
  while (have.some(l => used[l] < want[l])) {
    const left = have.filter(l => used[l] < want[l]), tot = left.reduce((a, l) => a + mix[l], 0);
    let roll = rnd() * tot; const l = left.find(x => (roll -= mix[x]) < 0) || left[0];
    out.push(pools[l][used[l]++]);
  }
  return out;
}
// 这一组在当前难度下没有题
function qlEmpty() {
  stage.innerHTML = "";
  const card = el("section", "card");
  const available = set ? members(set.key) : [];
  card.append(el("h3", null, available.length ? `这一组没有「${qlName(qLevel)}」难度的题` : "暂无可用题目，请从目录选择其他题组。"), el("p", "sub", available.length ? qlMixText(qLevel) + " 可以换一组，或者在“设置”里换难度等级。" : "学习记录仍然保留。"));
  const row = el("div", "actions");
  if (available.length) {
    const all = el("button", "btn", "练习此组全部难度"); all.type = "button";
    all.addEventListener("click", () => {
      set.qs = set.key.startsWith("listen:") ? listeningInterleave(available, set.key) : available;
      idx = bStart = score = 0; answers = {}; renderToc(); beginBatch();
    }); row.append(all);
  }
  if (qLevel === "zero") { const b = el("button", "btn", "去做零基础入门"); b.type = "button"; b.addEventListener("click", () => startSet("fr-r0", true)); row.append(b); }
  const s = el("button", "btn ghost", "去设置"); s.type = "button"; s.addEventListener("click", () => switchView("settings")); row.append(s);
  card.append(row); stage.append(card);
}
// 设置页的“难度等级”
function qlSection(wrap) {
  const sec = setSection(wrap, "难度等级", "普通语法题组按所设比例出题；计划与复习严格使用目录所选难度，未选择时使用此处难度。零基础入口、听力目录与游戏保留各自规则。");
  const note = el("p", "sub");
  sec.append(setSelectRow("setQLevel", "难度等级", QL_OPTS, qLevel, val => {
    qLevel = val; try { localStorage.setItem("fq-qlevel", val); } catch (e) {}
    note.textContent = qlMixText(val);
    if (typeof planRefresh === "function") planRefresh();
    if (typeof set !== "undefined" && set && set.key !== "fr-r0" && !/^(tour|listen):/.test(set.key)) { set = makeSet(set.key); idx = 0; bStart = 0; answers = {}; score = 0; }   // 回到答题页时按新难度重新排题
  }), note);
  note.textContent = qlMixText(qLevel);
}
