// Each listening format has a stable question ID and its own scored attempt.
const listeningAttempts = new WeakMap();
const LISTEN_LABELS = {
 comprehension:['理解选择','Comprehension','Compréhension'],cloze:['关键词填空','Keyword gaps','Mots à compléter'],order:['复原句子','Rebuild the sentence','Reconstituer la phrase'],
 singlePending:['点击选项提交答案。','Select an option to check your answer.','Choisissez une option pour vérifier votre réponse.'],
 pending:['完成练习后提交答案，查看对错与原文。','Complete the exercise, then submit to see the answer and original.','Terminez l’exercice puis validez pour voir la correction et le texte original.'],
 mode:['听力题型','Listening format','Format d’écoute'],gap:['空','Gap','Trou'],select:['请选择','Choose','Choisissez'],submit:['提交答案','Check answer','Vérifier'],
 clozeHelp:['听录音，选择每个空中实际听到的词语。','Listen and select the words you hear for each gap.','Écoutez et choisissez les mots entendus pour chaque trou.'],
 orderHelp:['点击词块依次组成原句；点击已选词块可移回。标点在答案中恢复。','Select the words in the order heard; select a placed word to return it. Punctuation is restored in the answer.','Placez les mots dans l’ordre entendu ; cliquez sur un mot placé pour le retirer. La ponctuation revient dans la réponse.'],
 longHelp:['长材料按句练习，播放按钮仍播放完整材料。','Practise one sentence at a time; the audio plays the full passage.','Travaillez phrase par phrase ; l’audio lit le texte complet.'],
 sentence:['练习句子','Practice sentence','Phrase à travailler'],sentenceN:['第','Sentence','Phrase'],assembled:['已排列的句子','Your sentence','Votre phrase'],bank:['待选词块','Available words','Mots disponibles'],
 add:['添加词块','Add word','Ajouter le mot'],remove:['移回词块','Return word','Retirer le mot'],undo:['撤回一步','Undo','Annuler'],reset:['清空排列','Clear','Effacer'],
 correct:['回答正确！','Correct!','Bonne réponse !'],wrong:['再对照原句听一遍。','Listen again and compare with the original.','Réécoutez et comparez avec la phrase originale.'],
 original:['原文：','Original:','Texte original :'],your:['你的答案：','Your answer:','Votre réponse :'],answer:['正确答案：','Correct answer:','Bonne réponse :'],
 count:['已排列','Placed','Placés'],locked:['本题已提交，可查看原文与回听录音。','Answer submitted. You can review the text and replay the audio.','Réponse envoyée. Vous pouvez relire le texte et réécouter.']
};
function listeningLabel(k){return LISTEN_LABELS[k][UI_LANG==='fr'?2:UI_LANG==='en'?1:0];}
function listeningShuffle(values){
 const a=values.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}
 if(a.length>1&&a.every((x,i)=>x===values[i]))a.push(a.shift());return a;
}
function listeningWords(text){return text.match(/[\p{L}\p{N}]+(?:[’'][\p{L}\p{N}]+)*/gu)||[];}
function listeningSentenceRanges(text){return Array.from(text.matchAll(/[^.!?…]+[.!?…]+["»]?|[^.!?…]+$/g),m=>({text:m[0].trim(),start:m.index,end:m.index+m[0].length})).filter(s=>s.text);}
function listeningSentences(text){return listeningSentenceRanges(text).map(s=>s.text).filter(s=>listeningWords(s).length>1);}
function listeningAudioParts(item,run){
 if(!run||run.mode==='comprehension')return [{text:item.audio}];
 if(run.mode==='order')return [{text:item.audio,clipText:listeningSentences(item.audio)[run.sentence]}];
 const gaps=LISTENING_GAPS[item.audio];return listeningSentenceRanges(item.audio).filter(s=>gaps.some(g=>g.start<s.end&&g.end>s.start)).map(s=>({text:item.audio,clipText:s.text}));
}
function listeningPlay(item,run,button){
 if(item.phonetic)return phoneticPlay(item.audio,button);
 if(!run||run.mode==='comprehension')return speak(item.audio,studyAudioRate(),button);
 return studySpeakSequence(listeningAudioParts(item,run),studyAudioRate(),button);
}
function listeningWordKey(text){return text.normalize('NFC').replace(/’/g,"'").toLocaleLowerCase('fr');}
function listeningMap(){if(!listeningAttempts.has(answers))listeningAttempts.set(answers,new Map());return listeningAttempts.get(answers);}
function listeningRun(item){
 if(!item.audio||!LISTENING_GAPS[item.audio])return null;
 const map=listeningMap();let run=map.get(item.id);
 if(run?.answered&&answers[idx]===undefined){map.delete(item.id);run=null;}
 if(!run){run={mode:item.listeningMode||'comprehension',answered:false,sentence:item.listeningSentence||0,chosen:[],gaps:[],options:LISTENING_GAPS[item.audio].map(b=>listeningShuffle(b.options))};map.set(item.id,run);}
 return run;
}
function listeningToolbar(item,card,run){
 if(run?.mode==='comprehension')card.append(el('div','listening-mode',listeningLabel(run.mode)));
}
function listeningRecordText(item,run){
 if(run.mode==='cloze')return {correct:LISTENING_GAPS[item.audio].map(b=>b.options[0]).join(' / '),chosen:run.gaps.join(' / ')};
 const sentence=listeningSentences(item.audio)[run.sentence];return {correct:sentence,chosen:run.chosen.map(i=>run.words[i]).join(' ')};
}
function listeningIsCorrect(item,run){
 if(run.mode==='cloze')return LISTENING_GAPS[item.audio].every((b,i)=>run.gaps[i]===b.options[0]);
 return run.chosen.length===run.words.length&&run.chosen.every((id,i)=>listeningWordKey(run.words[id])===listeningWordKey(run.words[i]));
}
function listeningSubmit(item,run,card){
 if(answers[idx]!==undefined||run.answered)return;card._listeningCancelDrag?.();
 const complete=run.mode==='cloze'?LISTENING_GAPS[item.audio].every((b,i)=>run.gaps[i]):run.chosen.length===run.words.length;if(!complete)return;
 const right=listeningIsCorrect(item,run),text=listeningRecordText(item,run);run.answered=true;run.right=right;run.result=text;
 answers[idx]=right?item.a:(item.a+1)%item.opts.length;score=calcScore();
 record({...item,cat:item.cat+' · '+LISTEN_LABELS[run.mode][0],opts:[text.correct,text.chosen],a:0},right?0:1,right);comboHit('quiz',right);
 paintAnswer(answers[idx],[],card,[]);
}

// Pointer events cover mouse, pen and touch without native HTML drag/scroll conflicts.
function listeningReorder(target,run,draw){
 let drag=null,suppressClick=false;
 const editable=()=>!run.answered&&answers[idx]===undefined;
 const focus=id=>target.querySelector('[data-word-id="'+id+'"]')?.focus?.({preventScroll:true});
 const finish=commit=>{
  if(!drag)return;const state=drag;drag=null;
  if(state.active){suppressClick=true;if(commit&&editable())run.chosen=Array.from(target.children,b=>Number(b.dataset.wordId));}
  state.button.classList.remove('is-dragging');target.classList.remove('is-reordering');
  try{if(state.button.hasPointerCapture?.(state.pointer))state.button.releasePointerCapture(state.pointer);}catch(e){}
  if(state.active){draw();focus(state.id);}
 };
 target.addEventListener('pointerdown',e=>{
  const button=e.target.closest?.('[data-word-id]');suppressClick=false;
  if(!button||button.disabled||!editable()||drag||e.isPrimary===false||(e.button!==undefined&&e.button!==0))return;
  drag={button,id:Number(button.dataset.wordId),pointer:e.pointerId,x:e.clientX,y:e.clientY,active:false};
  try{button.setPointerCapture?.(e.pointerId);}catch(e){}
 });
 target.addEventListener('pointermove',e=>{
  if(!drag||e.pointerId!==drag.pointer||!editable())return;
  if(!drag.active&&Math.hypot(e.clientX-drag.x,e.clientY-drag.y)<7)return;
  drag.active=true;e.preventDefault();drag.button.classList.add('is-dragging');target.classList.add('is-reordering');
  const bounds=target.getBoundingClientRect();if(e.clientX<bounds.left||e.clientX>bounds.right||e.clientY<bounds.top||e.clientY>bounds.bottom)return;
  let nearest=null,distance=Infinity;
  for(const button of target.children){if(button===drag.button)continue;const box=button.getBoundingClientRect(),dx=Math.max(box.left-e.clientX,0,e.clientX-box.right),dy=Math.max(box.top-e.clientY,0,e.clientY-box.bottom),d=dx*dx+dy*dy;if(d<distance){distance=d;nearest={button,box};}}
  if(nearest){const {button,box}=nearest,before=e.clientY<box.top||(e.clientY<=box.bottom&&e.clientX<(box.left+box.right)/2);const anchor=before?button:button.nextSibling;if(anchor!==drag.button&&drag.button.nextSibling!==anchor){target.insertBefore(drag.button,anchor);try{drag.button.setPointerCapture?.(drag.pointer);}catch(e){}}}
 });
 target.addEventListener('pointerup',e=>{if(!drag||e.pointerId!==drag.pointer)return;const b=target.getBoundingClientRect(),inside=e.clientX>=b.left&&e.clientX<=b.right&&e.clientY>=b.top&&e.clientY<=b.bottom;if(drag.active)e.preventDefault();finish(inside);});
 target.addEventListener('pointercancel',e=>{if(drag?.pointer===e.pointerId)finish(false);});
 target.addEventListener('lostpointercapture',e=>{if(drag?.pointer===e.pointerId)finish(false);});
 target.addEventListener('dragstart',e=>e.preventDefault());
 target.addEventListener('click',e=>{if(suppressClick){suppressClick=false;e.preventDefault();e.stopImmediatePropagation();}},true);
 target.addEventListener('keydown',e=>{
  if(!e.altKey||!['ArrowLeft','ArrowRight'].includes(e.key))return;
  const button=e.target.closest?.('[data-word-id]');if(!button||!editable())return;e.preventDefault();e.stopPropagation();finish(false);
  const id=Number(button.dataset.wordId),from=run.chosen.indexOf(id),to=from+(e.key==='ArrowLeft'?-1:1);if(from<0||to<0||to>=run.chosen.length)return;
  run.chosen.splice(from,1);run.chosen.splice(to,0,id);draw();focus(id);
 });
 return ()=>finish(false);
}

function listeningRender(item,card,run){
 card._listeningRun=run;const area=el('div','listening-exercise');area.dataset.mode=run.mode;
 const submit=el('button','btn',listeningLabel('submit'));submit.id='listeningSubmit';submit.type='button';submit.disabled=true;submit.addEventListener('click',()=>listeningSubmit(item,run,card));
 if(run.mode==='cloze'){
  const passage=el('div','listening-gap-text');passage.lang='fr';let cursor=0;
  LISTENING_GAPS[item.audio].forEach((gap,i)=>{
   passage.append(document.createTextNode(item.audio.slice(cursor,gap.start)));
   if(LISTENING_GAPS[item.audio].length===1){passage.append(el('strong','listening-blank','［ … ］'));cursor=gap.end;return;}
   const select=el('select','listening-gap');select.setAttribute('aria-label',listeningLabel('gap')+' '+(i+1));
   const placeholder=el('option',null,'['+(i+1)+'] '+listeningLabel('select'));placeholder.value='';select.append(placeholder);
   run.options[i].forEach(value=>{const option=el('option',null,value);option.value=value;select.append(option);});select.value=run.gaps[i]||'';
   select.addEventListener('change',()=>{run.gaps[i]=select.value;submit.disabled=!LISTENING_GAPS[item.audio].every((b,j)=>run.gaps[j]);});passage.append(select);cursor=gap.end;
  });passage.append(document.createTextNode(item.audio.slice(cursor)));area.append(passage);submit.disabled=!LISTENING_GAPS[item.audio].every((b,i)=>run.gaps[i]);
 }else{
  const sentences=listeningSentences(item.audio);
  if(!run.words){run.words=listeningWords(sentences[run.sentence]);run.bank=listeningShuffle(run.words.map((_,i)=>i));}
  const target=el('div','listening-word-tray listening-built'),bank=el('div','listening-word-tray');target.setAttribute('role','group');target.setAttribute('aria-label',listeningLabel('assembled'));bank.setAttribute('role','group');bank.setAttribute('aria-label',listeningLabel('bank'));target.lang=bank.lang='fr';
  const space=el('div','listening-sentence-space'),sizer=el('div','listening-word-tray listening-sizer');sizer.setAttribute('aria-hidden','true');sizer.lang='fr';run.bank.forEach(id=>sizer.append(el('span','listening-word',run.words[id])));space.append(sizer,target);
  const controls=el('div','actions listening-edit-actions'),undo=el('button','btn ghost'),reset=el('button','btn ghost');
  for(const [button,key,icon]of[[undo,'undo','↩️'],[reset,'reset','🗑️']]){button.type='button';button.title=listeningLabel(key);button.setAttribute('aria-label',listeningLabel(key));const glyph=el('span',null,icon);glyph.setAttribute('aria-hidden','true');button.append(glyph);}
  const draw=()=>{
   target.replaceChildren();bank.replaceChildren();
   run.chosen.forEach((id,pos)=>{const b=el('button','listening-word',run.words[id]);b.type='button';b.dataset.wordId=id;b.draggable=false;b.setAttribute('aria-keyshortcuts','Alt+ArrowLeft Alt+ArrowRight');b.setAttribute('aria-description',UI_LANG==='fr'?'Faites glisser pour réordonner, ou utilisez Alt et les flèches gauche/droite.':UI_LANG==='en'?'Drag to reorder, or use Alt and the left/right arrow keys.':'拖动可调整顺序，也可按 Alt 加左右方向键。');b.setAttribute('aria-label',listeningLabel('remove')+' '+run.words[id]+' ('+(pos+1)+')');b.addEventListener('click',()=>{if(run.answered||answers[idx]!==undefined)return;run.chosen.splice(pos,1);draw();bank.querySelector('button:not(:disabled)')?.focus?.();});target.append(b);});
   run.bank.forEach(id=>{const b=el('button','listening-word',run.words[id]);b.type='button';b.disabled=run.chosen.includes(id);if(b.disabled){b.classList.add('is-selected');b.setAttribute('aria-hidden','true');}b.setAttribute('aria-label',listeningLabel('add')+' '+run.words[id]+' ('+(id+1)+')');b.addEventListener('click',()=>{if(run.answered||answers[idx]!==undefined||run.chosen.includes(id))return;run.chosen.push(id);draw();(bank.querySelector('button:not(:disabled)')||submit).focus?.();});bank.append(b);});
   submit.disabled=run.chosen.length!==run.words.length;undo.disabled=reset.disabled=!run.chosen.length;
  };
  undo.addEventListener('click',()=>{run.chosen.pop();draw();});reset.addEventListener('click',()=>{run.chosen=[];draw();});controls.append(undo,reset);area.append(space,bank,controls);card._listeningCancelDrag=listeningReorder(target,run,draw);draw();
 }
 if(run.mode==='cloze'&&LISTENING_GAPS[item.audio].length===1){
  const choices=el('div','opts listening-single-options');
  run.options[0].forEach((value,i)=>{const b=el('button','opt');b.type='button';b.dataset.answer=value;b.append(el('span','key',String.fromCharCode(65+i)),el('span',null,value));b.addEventListener('click',()=>{if(run.answered||answers[idx]!==undefined)return;run.gaps[0]=value;listeningSubmit(item,run,card);});choices.append(b);});area.append(choices);
 }else area.append(submit);card.append(area);
}
function listeningPaint(item,card){
 const run=card._listeningRun;if(!run||run.mode==='comprehension')return false;
 card._listeningCancelDrag?.();card.querySelectorAll('#listeningSubmit,.listening-exercise button,.listening-exercise select,.listening-mode select').forEach(b=>b.disabled=true);
 card.querySelectorAll('.listening-single-options button').forEach(b=>{if(b.dataset.answer===LISTENING_GAPS[item.audio][0].options[0])b.classList.add('correct');else if(b.dataset.answer===run.gaps[0])b.classList.add('wrong');});
 const exp=card.querySelector('#explain');exp.classList.remove('pending');exp.replaceChildren();const right=run.right;
 exp.append(el('b',right?'ok':'no',listeningLabel(right?'correct':'wrong')));
 const text=run.result||listeningRecordText(item,run);
 exp.append(el('p',null,listeningLabel('your')+' '+text.chosen),el('p','transcript',listeningLabel('answer')+' '+text.correct));
 if(run.mode==='cloze')exp.append(el('p','transcript',listeningLabel('original')+' '+item.audio));
 exp.append(el('p','sub',listeningLabel('locked')));const hb=card.querySelector('#hintBtn');if(hb)hb.disabled=true;
 const next=card.querySelector('#nextBtn');next.disabled=false;updateProgress(idx+1);next.focus({preventScroll:true});return true;
}
