// 法语排版：问号、感叹号、冒号、分号和书名号内侧用不换行空格
const frT = s => s.replace(/ ([?!:;»])/g, " $1").replace(/« /g, "« ");
const LET = "ABCD";
const exNorm = s => String(s || "").normalize("NFC").trim().toLowerCase().replace(/[’`´]/g, "'").replace(/\s+/g, " ").replace(/[.,;:!?»«]+$/g, "").trim();
const exBare = s => exNorm(s).normalize("NFD").replace(/[̀-ͯ]/g, "");
const EX_PTS = { listen: 1.5, reading: 2, seven: 2, cloze: 1.5, grammar: 1.5, fix: 1, essay: 25 };

// 短文改错：把标准答案定位到具体的词
const FIX_TOKS = EX.fix.text.split(/\s+/);
const fixCore = t => exNorm(t);
EX.fix.key.forEach(k => {
  let seen = 0;
  k.i = FIX_TOKS.findIndex(t => fixCore(t) === k.w && ++seen === k.occ);
});

// ---------- 草稿（只存在本机浏览器） ----------
const EX_DRAFT_KEY = "fq-exam-" + EX.id;
let exState = null;      // { ans:{}, edits:{}, essay:"", used:已用秒数, paused:是否手动暂停, plays:{} }
let exResult = null;     // 交卷后的成绩
let exTimer = null, exSel = null, exHist = null, exConfirmReset = false;
function exLoad() {
  if (exState) return;
  try { exState = JSON.parse(localStorage.getItem(EX_DRAFT_KEY) || "null"); } catch (e) { exState = null; }
  if (!exState || typeof exState !== "object") exState = {};
  exState.ans ||= {}; exState.edits ||= {}; exState.plays ||= {}; exState.essay ||= "";
  if (exState.result) exResult = exState.result;
  if (typeof exState.used !== "number") exState.used = 0;   // 旧草稿按开卷时刻算，不准，从 0 重新计
  delete exState.start;
}
// ---------- 计时：只算真正在做卷子的时间 ----------
// 停在“模拟卷”页、页面在前台、没交卷、没手动暂停时才走；切到别的页、锁屏、切走应用都会自动停
let exRunSince = 0;   // 这一段从什么时候开始走（0 = 没在走）
const exUsed = () => exState.used + (exRunSince ? (Date.now() - exRunSince) / 1000 : 0);
const exShouldRun = () => !!exState && !exResult && !exState.paused && view === "exam" && document.visibilityState === "visible";
function exPause() {
  if (!exRunSince) return;
  exState.used = exUsed(); exRunSince = 0; exSave();
}
function exResume() { if (!exRunSince && exShouldRun()) exRunSince = Date.now(); }
document.addEventListener("visibilitychange", () => { if (document.visibilityState === "visible") exResume(); else exPause(); });
addEventListener("pagehide", exPause);
function exSave() { try { localStorage.setItem(EX_DRAFT_KEY, JSON.stringify({ ...exState, result: exResult })); } catch (e) {} }

// ---------- 听力朗读：男女两种声音 ----------
function exVoices() {
  const fr = tts ? tts.getVoices().filter(v => /^fr/i.test(v.lang)) : [];
  const f = fr.find(v => /amélie|amelie|audrey|aurélie|marie|virginie|julie|céline|hortense|denise|léa|female/i.test(v.name));
  const m = fr.find(v => /thomas|daniel|nicolas|henri|paul|claude|mathieu|male/i.test(v.name) && !/female/i.test(v.name));
  return { F: f || frVoice, M: m || frVoice };
}
function exSpeak(lines, rate, btn) {
  return studySpeakSequence(lines.map(([role,text])=>({role,text})),rate,btn);
}

// ---------- 通用小部件 ----------
function exPart(id, title, rule) {
  const sec = el("section", "card ex-part");
  sec.id = "ex-" + id;
  sec.append(el("h3", null, title));
  if (rule) sec.append(el("p", "ex-rule", rule));
  return sec;
}
function exMcq(n, q, opts, a, exp) {
  const box = el("div", "ex-q");
  box.id = "exq-" + n;
  const qt = el("p", "ex-qt");
  qt.append(el("span", "n", n + "."), el("span", null, frT(q)));
  const row = el("div", "ex-opts");
  const chosen = exState.ans[n];
  opts.forEach((o, i) => {
    const b = el("button", "ex-opt");
    b.type = "button";
    b.append(el("span", "k", LET[i]), el("span", null, frT(o)));
    b.setAttribute("aria-pressed", String(chosen === i));
    if (exResult) {
      b.disabled = true;
      if (i === a) b.classList.add("correct");
      else if (chosen === i) b.classList.add("wrong");
    } else {
      b.addEventListener("click", () => {
        exState.ans[n] = i; exSave();
        row.querySelectorAll(".ex-opt").forEach((x, j) => x.setAttribute("aria-pressed", String(j === i)));
        exUpdateCount();
      });
    }
    row.append(b);
  });
  box.append(qt, row);
  if (exResult) box.append(exWhy(chosen === a, LET[a], exp, chosen === undefined));
  return box;
}
function exWhy(ok, right, exp, blank) {
  const p = el("p", "ex-why");
  p.append(el("b", ok ? "ok" : "no", ok ? "✓ 正确。" : blank ? `未作答，答案 ${right}。` : `✗ 答案 ${right}。`));
  if (exp) p.append(document.createTextNode(" " + exp));
  return p;
}
// 把含 {n} 和 **粗体** 的段落拆成节点
function exPara(text, gap) {
  const p = el("p");
  text.split(/(\{\d+\}|\*\*[^*]+\*\*)/).forEach(part => {
    if (!part) return;
    const m = part.match(/^\{(\d+)\}$/);
    if (m) p.append(gap(Number(m[1])));
    else if (part.startsWith("**")) p.append(el("b", null, frT(part.slice(2, -2))));
    else p.append(document.createTextNode(frT(part)));
  });
  return p;
}

// ---------- 各部分 ----------
function exListen() {
  const sec = exPart("listen", "第一部分 · 听力（30 分）", "点 ▶ 播放 由设备朗读录音（女声、男声尽量区分）。第一节每段建议只听 1 遍，第二节每段听 2 遍；交卷后可以看原文。");
  [1, 2].forEach(s => {
    sec.append(el("p", "ex-sub", s === 1 ? "第一节（共 5 小题；每小题 1.5 分）" : "第二节（共 15 小题；每小题 1.5 分）"));
    EX.listen.filter(t => t.sec === s).forEach(t => {
      const blk = el("div", "ex-block");
      const ns = t.qs.map(q => q.n);
      const head = el("div", "ex-listen");
      head.append(el("span", "ex-label", ns.length > 1 ? `第 ${t.id.slice(1)} 段材料 · 第 ${ns[0]}–${ns[ns.length - 1]} 题` : `第 ${t.id.slice(1)} 段对话`));
      const play = studyAudioButton("play"); play.type = "button";
      const note = el("span", "listen-note");
      const showCount = () => { const c = exState.plays[t.id] || 0; note.textContent = `已播放 ${c} 遍 · 建议 ${s === 1 ? 1 : 2} 遍`; };
      showCount();
      if (tts || typeof Audio !== "undefined") {
        const slow=studyAudioButton("slow");
        const stop = studyAudioButton("stop"); stop.type = "button";
        stop.addEventListener("click", () => { studyAudioStop(); play.setAttribute("aria-pressed", "false"); });
        head.append(play, slow, stop);
        studyAudioControls(head, () => { exSpeak(t.lines, studyAudioRate(), play); exState.plays[t.id] = (exState.plays[t.id] || 0) + 1; exSave(); showCount(); });
        head.append(note);
      } else {
        play.disabled = true;
        head.append(play, el("span", "listen-note", "这台设备不能朗读，可交卷后看原文"));
      }
      blk.append(head);
      t.qs.forEach(q => blk.append(exMcq(q.n, q.q, q.o, q.a, q.e)));
      if (exResult) {
        const sc = el("div", "ex-script");
        t.lines.forEach(([who, text]) => { const d = el("div"); d.append(el("b", null, t.lines.length > 1 ? who : ""), el("span", null, frT(text))); sc.append(d); });
        blk.append(sc);
      }
      sec.append(blk);
    });
  });
  return sec;
}
function exReading() {
  const sec = exPart("reading", "第二部分 · 阅读理解（40 分）");
  sec.append(el("p", "ex-sub", "第一节（共 15 小题；每小题 2 分）"));
  EX.reading.forEach(r => {
    const blk = el("div", "ex-block");
    blk.append(el("span", "ex-label", r.id));
    const pass = el("div", "ex-pass");
    if (r.ad) {
      const ad = el("div", "ad");
      ad.append(el("p", "ttl", frT(r.ad.title)));
      r.ad.items.forEach(([h, p]) => { ad.append(el("h4", null, frT(h)), el("p", null, frT(p))); });
      const f = el("p", null, frT(r.ad.foot)); f.style.fontStyle = "italic"; ad.append(f);
      pass.append(ad);
    } else r.paras.forEach(p => pass.append(el("p", null, frT(p))));
    blk.append(pass);
    r.qs.forEach(q => blk.append(exMcq(q.n, q.q, q.o, q.a, q.e)));
    sec.append(blk);
  });
  // 七选五
  const S = EX.seven;
  sec.append(el("p", "ex-sub", "第二节 · 七选五（共 5 小题；每小题 2 分）"));
  sec.append(el("p", "ex-rule", "从短文后的选项中选出能填入空白处的最佳选项，有两项为多余选项。"));
  const pass = el("div", "ex-pass");
  pass.append(el("p", "ttl", frT(S.title)));
  S.paras.forEach(t => pass.append(exPara(t, n => {
    const sel = el("select", "ex-sel");
    sel.setAttribute("aria-label", `第 ${n} 题`);
    sel.append(new Option(`${n}. 选择`, ""));
    Object.keys(S.opts).forEach(k => sel.append(new Option(`${n}. ${k}`, k)));
    sel.value = exState.ans[n] || "";
    if (exResult) {
      sel.disabled = true;
      sel.classList.add(exState.ans[n] === S.key[n] ? "correct" : "wrong");
    } else sel.addEventListener("change", () => { exState.ans[n] = sel.value || undefined; exSave(); exUpdateCount(); });
    return sel;
  })));
  sec.append(pass);
  const ul = el("ul", "ex-seven");
  Object.entries(S.opts).forEach(([k, v]) => { const li = el("li"); li.append(el("b", null, k + "."), el("span", null, frT(v))); ul.append(li); });
  sec.append(ul);
  if (exResult) [36, 37, 38, 39, 40].forEach(n => {
    const w = exWhy(exState.ans[n] === S.key[n], S.key[n], S.exp[n], !exState.ans[n]);
    w.prepend(el("span", null, n + ". ")); w.style.paddingLeft = "0"; sec.append(w);
  });
  return sec;
}
function exCloze() {
  const C = EX.cloze, sec = exPart("cloze", "第三部分 · 语言知识运用（45 分）");
  sec.append(el("p", "ex-sub", "第一节 · 完形填空（共 20 小题；每小题 1.5 分）"));
  const gaps = {};
  const word = n => { const q = C.qs.find(x => x[0] === n); const i = exState.ans[n]; return i === undefined ? "" : q[1][i]; };
  const pass = el("div", "ex-pass");
  C.paras.forEach(t => pass.append(exPara(t, n => {
    const g = el("span", "ex-gap");
    const fill = () => { g.textContent = ""; g.append(el("span", "n", String(n)), document.createTextNode(word(n) || "   ")); };
    fill(); gaps[n] = fill;
    if (exResult) { const q = C.qs.find(x => x[0] === n); g.classList.add(exState.ans[n] === q[2] ? "correct" : "wrong"); }
    return g;
  })));
  sec.append(pass);
  const grid = el("div", "ex-cloze-grid");
  C.qs.forEach(([n, opts, a, exp]) => {
    const box = el("div", "ex-q"); box.id = "exq-" + n;
    const row = el("div", "ex-opts");
    opts.forEach((o, i) => {
      const b = el("button", "ex-opt"); b.type = "button";
      b.append(el("span", "k", LET[i]), el("span", null, o));
      b.setAttribute("aria-pressed", String(exState.ans[n] === i));
      if (exResult) { b.disabled = true; if (i === a) b.classList.add("correct"); else if (exState.ans[n] === i) b.classList.add("wrong"); }
      else b.addEventListener("click", () => {
        exState.ans[n] = i; exSave(); gaps[n]();
        row.querySelectorAll(".ex-opt").forEach((x, j) => x.setAttribute("aria-pressed", String(j === i)));
        exUpdateCount();
      });
      row.append(b);
    });
    box.append(el("span", "n", n + "."), row);
    grid.append(box);
  });
  sec.append(grid);
  if (exResult) C.qs.filter(q => q[3] || exState.ans[q[0]] !== q[2]).forEach(([n, opts, a, exp]) => {
    const w = exWhy(exState.ans[n] === a, `${LET[a]} ${opts[a]}`, exp, exState.ans[n] === undefined);
    w.prepend(el("span", null, n + ". ")); w.style.paddingLeft = "0"; sec.append(w);
  });

  const G = EX.grammar;
  sec.append(el("p", "ex-sub", "第二节 · 语法填空（共 10 小题；每小题 1.5 分）"));
  sec.append(el("p", "ex-rule", "在空白处填入 1 个适当的词，或括号内词的正确形式（动词可用复合时态）。注意重音符号，交卷后按标准答案判分。"));
  const gp = el("div", "ex-pass");
  G.paras.forEach(t => gp.append(exPara(t, n => {
    const span = el("span");
    const inp = el("input", "ex-in");
    inp.type = "text"; inp.autocomplete = "off"; inp.spellcheck = false; inp.setAttribute("autocapitalize", "off");
    inp.placeholder = String(n); inp.setAttribute("aria-label", `第 ${n} 题`);
    inp.value = exState.ans[n] || "";
    span.append(inp);
    if (G.hint[n]) span.append(el("span", "ex-hint", ` (${G.hint[n]})`));
    if (exResult) {
      inp.disabled = true;
      const ok = G.key[n].some(k => exNorm(k) === exNorm(exState.ans[n]));
      inp.classList.add(ok ? "correct" : "wrong");
      if (!ok) span.append(el("span", "ex-fix", " → " + G.key[n].join(" / ")));
    } else inp.addEventListener("input", () => { exState.ans[n] = inp.value; exSave(); exUpdateCount(); });
    return span;
  })));
  sec.append(gp);
  if (exResult) Object.keys(G.key).map(Number).forEach(n => {
    const ok = G.key[n].some(k => exNorm(k) === exNorm(exState.ans[n]));
    const near = !ok && G.key[n].some(k => exBare(k) === exBare(exState.ans[n]));
    const w = exWhy(ok, G.key[n].join(" / "), (near ? "（只差重音符号）" : "") + G.exp[n], !exNorm(exState.ans[n]));
    w.prepend(el("span", null, n + ". ")); w.style.paddingLeft = "0"; sec.append(w);
  });
  return sec;
}
function exFix() {
  const F = EX.fix, sec = exPart("fix", "第四部分 · 写作（35 分）");
  sec.append(el("p", "ex-sub", "第一节 · 短文改错（10 分）"));
  sec.append(el("p", "ex-rule", "文中共 10 处错误，每处只涉及一个词的增加、删除或修改。点一个词，然后选择：改成别的词、删掉它，或在它前面加一个词。最多改 10 处。"));
  const box = el("div", "ex-fixtext");
  const pop = el("div", "ex-pop"); pop.hidden = true;
  const edits = exState.edits;
  const count = () => Object.keys(edits).length;
  const keyAt = new Map(F.key.map(k => [k.i + ":" + k.t, k]));
  const draw = () => {
    box.textContent = "";
    FIX_TOKS.forEach((tok, i) => {
      const b = el("button", "tok"); b.type = "button";
      const ins = edits[i + ":ins"], mod = edits[i + ":mod"], del = edits[i + ":del"];
      if (ins) { const s = el("span", "ins", "∧" + ins + " "); b.append(s); }
      b.append(document.createTextNode(tok));
      if (del) b.classList.add("del");
      if (mod) { b.classList.add("mod"); b.append(el("span", "ann", mod)); }
      if (exResult) {
        b.disabled = true;
        const mine = ["ins", "mod", "del"].filter(t => edits[i + ":" + t]);
        const right = mine.length && mine.every(t => { const k = keyAt.get(i + ":" + t); return k && (t === "del" || k.ans.some(a => exNorm(a) === exNorm(edits[i + ":" + t]))); });
        if (mine.length) b.classList.add(right ? "ok-mark" : "no-mark");
        else if (F.key.some(k => k.i === i)) b.classList.add("miss-mark");
      } else b.addEventListener("click", () => { exSel = i; openPop(); });
      box.append(b, document.createTextNode(" "));
    });
  };
  const openPop = () => {
    const i = exSel; pop.hidden = false; pop.textContent = "";
    pop.append(el("b", null, `所选：${FIX_TOKS[i]}`), el("span", "ex-count", `已改 ${count()}/10`));
    const room = k => edits[k] !== undefined || count() < 10;
    const mk = (label, solid, fn, dis) => { const b = el("button", "ex-small" + (solid ? " solid" : ""), label); b.type = "button"; b.disabled = !!dis; b.addEventListener("click", fn); return b; };
    const inMod = el("input", "ex-in"); inMod.placeholder = "改成…"; inMod.value = edits[i + ":mod"] || ""; inMod.setAttribute("aria-label", "改成");
    const inIns = el("input", "ex-in"); inIns.placeholder = "在前面加…"; inIns.value = edits[i + ":ins"] || ""; inIns.setAttribute("aria-label", "在前面加词");
    [inMod, inIns].forEach(x => { x.autocomplete = "off"; x.spellcheck = false; x.setAttribute("autocapitalize", "off"); });
    const done = () => { exSave(); draw(); pop.hidden = true; exUpdateCount(); };
    pop.append(inMod, mk("修改", true, () => { const v = inMod.value.trim(); if (v) { delete edits[i + ":del"]; edits[i + ":mod"] = v; done(); } }, !room(i + ":mod")),
      mk("删除这个词", false, () => { delete edits[i + ":mod"]; edits[i + ":del"] = "1"; done(); }, !room(i + ":del")),
      inIns, mk("加词", true, () => { const v = inIns.value.trim(); if (v) { edits[i + ":ins"] = v; done(); } }, !room(i + ":ins")),
      mk("清除此处", false, () => { delete edits[i + ":mod"]; delete edits[i + ":del"]; delete edits[i + ":ins"]; done(); }),
      mk("取消", false, () => { pop.hidden = true; }));
    inMod.focus();
  };
  draw();
  sec.append(box, pop);
  if (exResult) {
    const ul = el("div");
    F.key.forEach((k, j) => {
      const mine = edits[k.i + ":" + k.t];
      const ok = mine !== undefined && (k.t === "del" || k.ans.some(a => exNorm(a) === exNorm(mine)));
      const fixTxt = k.t === "del" ? `删去 ${k.w}` : k.t === "ins" ? `${k.w} 前加 ${k.ans[0]}` : `${k.w} → ${k.ans[0]}`;
      const w = exWhy(ok, fixTxt, k.why, mine === undefined);
      w.prepend(el("span", null, (j + 1) + ". ")); w.style.paddingLeft = "0"; ul.append(w);
    });
    sec.append(ul);
  }

  sec.append(el("p", "ex-sub", "第二节 · 书面表达（25 分）"));
  sec.append(el("p", "ex-rule", EX.essay.prompt));
  const ta = el("textarea", "ex-essay");
  ta.setAttribute("aria-label", "作文");
  ta.spellcheck = false; ta.setAttribute("lang", "fr");
  ta.placeholder = "Chère Léa,\n\n…\n\nAmitiés,\nLi Hua";
  ta.value = exState.essay;
  const wc = el("span", "ex-count");
  const showWc = () => { wc.textContent = `约 ${exWords(ta.value)} 词（不含开头结尾）`; };
  showWc();
  if (exResult) ta.readOnly = true;
  else ta.addEventListener("input", () => { exState.essay = ta.value; exSave(); showWc(); });
  sec.append(ta, wc);
  if (exResult) sec.append(exEssayFeedback());
  return sec;
}
function exWords(t) {
  const body = t.replace(/^\s*ch[eè]re\s+l[ée]a\s*,?/i, "").replace(/amiti[ée]s\s*,?\s*(li\s+hua)?\s*$/i, "");
  return (body.match(/[A-Za-zÀ-ÿœæŒÆ]+/g) || []).length;
}

// ---------- 作文批改：请 Claude 按高考评分标准打分 ----------
let exSample;   // undefined: 还没问；null: 不可用
async function exGradeEssay() {
  const essay = exState.essay.trim();
  if (!essay) return { score: 0, band: "未作答", summary: "没有写作文。" };
  if (exSample === undefined) { if (LOCAL) exSample = null; else try { exSample = await claude.use("sample"); } catch (e) { exSample = null; } }
  if (!exSample) return null;
  const prompt = `你是高考英语阅卷老师，现在用同样的标准批改一篇法语 B1 水平的书面表达（满分 25 分）。
评分档次：第五档 21–25（完全完成任务，覆盖所有要点，语法结构和词汇丰富准确，几乎无错误，连贯）；第四档 16–20；第三档 11–15；第二档 6–10；第一档 1–5；与题目无关或未作答 0 分。词数明显不足 100 或超过很多要酌情扣分。
题目：${EX.essay.prompt}
学生作文：
"""
${essay}
"""
请只返回 JSON：{"score": 整数, "band": "第几档", "summary": "一两句中文总评", "points": ["要点覆盖情况，逐条中文"], "errors": [{"original": "原文片段", "correction": "改正后", "why": "中文说明"}], "improved": "在学生原文基础上修改后的法语版本（保留其内容）"}。errors 最多列 8 条最重要的。`;
  try {
    const r = await exSample.json(prompt, { modelTier: "default", cache: false });
    if (!r || typeof r.score !== "number") return null;
    r.score = Math.max(0, Math.min(25, Math.round(r.score)));
    return r;
  } catch (e) {
    return e && e.code === "not_granted" ? null : { error: true };
  }
}
function exEssayFeedback() {
  const box = el("div", "ex-fb");
  const fb = exResult.essay;
  if (fb === "pending") { box.append(el("p", "empty", "Claude 正在批改作文…")); return box; }
  if (LOCAL && !fb) {
    box.append(el("h4", null, "网页版不能自动批改作文"), el("p", null, "请对照下面的范文和评分档次（第五档 21–25 分 … 第一档 1–5 分）自己估分。"));
  } else if (!fb || fb.error) {
    box.append(el("h4", null, "作文暂时无法自动批改"), el("p", null, fb && fb.error ? "批改请求没有成功，可以点下面的按钮再试一次，或对照范文自己估分。" : "这个页面现在无法调用 Claude 批改，可以对照范文自己估分，或把作文发给我批改。"));
    const again = el("button", "ex-small solid", "重新批改作文"); again.type = "button";
    again.addEventListener("click", async () => { exResult.essay = "pending"; renderExam(); const r = await exGradeEssay(); exResult.essay = r || null; exFinish(); });
    box.append(again);
  } else {
    box.append(el("h4", null, `作文得分：${fb.score} / 25${fb.band ? " · " + fb.band : ""}`));
    if (fb.summary) box.append(el("p", null, fb.summary));
    const list = (title, arr, f) => { if (!arr || !arr.length) return; box.append(el("b", null, title)); const ul = el("ul"); arr.forEach(x => ul.append(el("li", null, f(x)))); box.append(ul); };
    list("要点", fb.points, x => String(x));
    list("主要错误", fb.errors, x => `${x.original} → ${x.correction}${x.why ? "：" + x.why : ""}`);
    if (fb.improved) { box.append(el("b", null, "修改后的版本")); box.append(el("div", "improved", fb.improved)); }
  }
  box.append(el("b", null, "参考范文"));
  box.append(el("div", "improved", EX.essay.model));
  return box;
}

// ---------- 判分、交卷、保存 ----------
function exAnswered() {
  let n = 0;
  for (let i = 1; i <= 60; i++) if (exState.ans[i] !== undefined && exState.ans[i] !== "") n++;
  for (let i = 61; i <= 70; i++) if (exNorm(exState.ans[i])) n++;
  return n;
}
function exScore() {
  const A = exState.ans, s = { listen: 0, reading: 0, seven: 0, cloze: 0, grammar: 0, fix: 0 };
  EX.listen.forEach(t => t.qs.forEach(q => { if (A[q.n] === q.a) s.listen += EX_PTS.listen; }));
  EX.reading.forEach(r => r.qs.forEach(q => { if (A[q.n] === q.a) s.reading += EX_PTS.reading; }));
  Object.entries(EX.seven.key).forEach(([n, k]) => { if (A[n] === k) s.seven += EX_PTS.seven; });
  EX.cloze.qs.forEach(([n, , a]) => { if (A[n] === a) s.cloze += EX_PTS.cloze; });
  Object.entries(EX.grammar.key).forEach(([n, ks]) => { if (ks.some(k => exNorm(k) === exNorm(A[n]))) s.grammar += EX_PTS.grammar; });
  EX.fix.key.forEach(k => { const m = exState.edits[k.i + ":" + k.t]; if (m !== undefined && (k.t === "del" || k.ans.some(a => exNorm(a) === exNorm(m)))) s.fix += EX_PTS.fix; });
  return s;
}
async function exSubmit() {
  clearInterval(exTimer);
  exPause();
  exResult = { parts: exScore(), essay: "pending", at: new Date().toISOString(), secs: Math.round(exUsed()) };
  if (typeof petRecordExam === "function") petRecordExam({exam:EX.id,at:exResult.at,answers:exState.ans});
  exSave();
  renderExam();
  $("ex-result")?.scrollIntoView({ block: "start" });
  const r = await exGradeEssay();
  exResult.essay = r || null;
  exFinish();
}
function exFinish() {
  exSave();
  if (view === "exam") renderExam();
  if (!dbRef || exResult.saved) return;
  const fb = exResult.essay;
  const p = exResult.parts;
  const objective = p.listen + p.reading + p.seven + p.cloze + p.grammar + p.fix;
  dbRef.collection("exams").add({
    exam: EX.id, at: exResult.at, secs: exResult.secs, objective, essay: fb && typeof fb.score === "number" ? fb.score : null,
    total: objective + (fb && typeof fb.score === "number" ? fb.score : 0), parts: p,
    answers: JSON.stringify(exState.ans), edits: JSON.stringify(exState.edits), essayText: exState.essay,
    essayFeedback: fb && typeof fb.score === "number" ? JSON.stringify(fb) : null,
  }).then(() => { exResult.saved = true; exSave(); exHist = null; }).catch(() => {});
}
function exUpdateCount() {
  const c = $("exCount");
  if (c) c.textContent = `已作答 ${exAnswered()}/70 · 改错 ${Object.keys(exState.edits).length}/10 · 作文 ${exWords(exState.essay)} 词`;
}
const exClock = s => `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;

async function exLoadHist() {
  if (!dbRef || exHist) return;
  try {
    const snap = await dbRef.collection("exams").where("exam", "==", EX.id).get();
    exHist = snap.docs.map(d => d.data()).sort((a, b) => String(b.at).localeCompare(String(a.at)));
    if (view === "exam") { const h = $("exHist"); if (h) fillHist(h); }
  } catch (e) { exHist = []; }
}
function fillHist(box) {
  box.textContent = "";
  if (!exHist || !exHist.length) return;
  box.append(el("b", null, "以往成绩"));
  const ul = el("ul", "ex-hist");
  exHist.slice(0, 5).forEach(h => ul.append(el("li", null, `${String(h.at).slice(0, 16).replace("T", " ")} · 总分 ${h.total}（客观题 ${h.objective}${h.essay != null ? ` + 作文 ${h.essay}` : "，作文未评"}）· 用时 ${exClock(h.secs || 0)}`)));
  box.append(ul);
}

function renderExam() {
  exLoad();
  stage.innerHTML = "";
  const wrap = el("div", "ex");
  const head = el("section", "card ex-head");
  head.append(el("h2", null, EX.title), el("p", "ex-rule", EX.sub));
  const meta = el("div", "ex-meta");
  const clock = el("span", "ex-clock");
  const pause = el("button", "btn ghost ex-pause"); pause.type = "button"; pause.id = "exPause";
  pause.addEventListener("click", () => {
    exState.paused = !exState.paused;
    if (exState.paused) exPause(); else { exSave(); exResume(); }
    tick();
  });
  meta.append(clock);
  if (!exResult) meta.append(pause);
  head.append(meta);
  const nav = el("nav", "ex-nav"); nav.setAttribute("aria-label", "试卷各部分");
  [["listen", "听力"], ["reading", "阅读"], ["cloze", "完形与语法填空"], ["fix", "改错与作文"]].forEach(([id, t]) => {
    const a = el("a", null, t); a.href = "#ex-" + id;
    a.addEventListener("click", e => { e.preventDefault(); $("ex-" + id)?.scrollIntoView({ block: "start", behavior: "smooth" }); });
    nav.append(a);
  });
  head.append(nav);
  const hist = el("div"); hist.id = "exHist"; fillHist(hist); head.append(hist);
  wrap.append(head);

  if (exResult) wrap.append(exResultCard());
  wrap.append(exListen(), exReading(), exCloze(), exFix());

  const bar = el("div", "ex-bar");
  const cnt = el("span", "ex-count"); cnt.id = "exCount";
  bar.append(cnt);
  const btns = el("div", "actions");
  if (exResult) {
    const redo = el("button", "btn", "清空重做"); redo.type = "button";
    redo.addEventListener("click", () => {
      if (!exConfirmReset) { exConfirmReset = true; redo.textContent = "再点一次确认清空"; return; }
      exConfirmReset = false; exResult = null; exState = { ans: {}, edits: {}, plays: {}, essay: "", used: 0 }; exRunSince = 0; exSave(); renderExam(); window.scrollTo(0, typeof cosTopH === "function" ? cosTopH() : 0);
    });
    const top = el("button", "btn ghost", "看成绩"); top.type = "button";
    top.addEventListener("click", () => $("ex-result")?.scrollIntoView({ block: "start", behavior: "smooth" }));
    btns.append(top, redo);
  } else {
    const sub = el("button", "btn", "交卷"); sub.type = "button";
    sub.addEventListener("click", () => {
      const left = 70 - exAnswered();
      if (left > 0 && !exConfirmReset) { exConfirmReset = true; sub.textContent = `还有 ${left} 题没做，再点一次交卷`; return; }
      exConfirmReset = false; exSubmit();
    });
    btns.append(sub);
  }
  bar.append(btns);
  wrap.append(bar);
  stage.append(wrap);
  exUpdateCount();

  clearInterval(exTimer);
  function tick() {
    const s = exResult ? exResult.secs : Math.floor(exUsed());
    clock.textContent = "";
    clock.classList.toggle("over", s > 120 * 60);
    clock.append(document.createTextNode(exResult ? "用时 " : "已用时 "), el("b", null, exClock(s)), document.createTextNode(" / 建议 120:00"));
    if (!exResult && exState.paused) clock.append(el("span", "ex-paused", " · 已暂停"));
    pause.textContent = exState.paused ? "继续计时" : "暂停";
  }
  exResume();
  tick();
  let n = 0;
  if (!exResult) exTimer = setInterval(() => {
    if (view !== "exam") { exPause(); clearInterval(exTimer); return; }
    exResume(); tick();
    if (++n % 15 === 0 && exRunSince) { exPause(); exResume(); }   // 每 15 秒存一次，关掉页面也不丢时间
  }, 1000);
  exLoadHist();
}
function exResultCard() {
  const p = exResult.parts, fb = exResult.essay;
  const essay = fb && typeof fb.score === "number" ? fb.score : null;
  const objective = p.listen + p.reading + p.seven + p.cloze + p.grammar + p.fix;
  const card = el("section", "card ex-part"); card.id = "ex-result";
  card.append(el("span", "tag", "成绩单"));
  const sc = el("p", "score", String(objective + (essay || 0)));
  sc.append(el("small", null, " / 150"));
  card.append(sc);
  if (fb === "pending") card.append(el("p", "ex-rule", "客观题已判完，作文正在由 Claude 批改，完成后总分会自动更新。"));
  else if (essay === null) card.append(el("p", "ex-rule", "作文没有自动评分，总分暂不含作文的 25 分。"));
  const t = el("table", "ex-table");
  const rows = [["听力", p.listen, 30], ["阅读理解（含七选五）", p.reading + p.seven, 40], ["完形填空", p.cloze, 30], ["语法填空", p.grammar, 15], ["短文改错", p.fix, 10], ["书面表达", fb === "pending" ? "批改中" : essay === null ? "—" : essay, 25]];
  const th = el("tr"); ["部分", "得分", "满分"].forEach(x => th.append(el("th", null, x))); t.append(th);
  rows.forEach(([a, b, c]) => { const tr = el("tr"); tr.append(el("td", null, a), el("td", null, String(b)), el("td", null, String(c))); t.append(tr); });
  card.append(t);
  card.append(el("p", "ex-rule", "下面每道题都标出了对错和解析；听力原文在每段题目下方。"));
  return card;
}
