  toc.append(el("div", "toc-book", "B1–B2 主题词汇 · 每个词最多六种题型"));
  toc.append(el("div", "toc-sec", "练习"));
  const ul0 = el("ul");
  const all = V_WORDS.length, allDone = vStats ? V_WORDS.filter(w => vState(w) === "done").length : 0;
  ul0.append(tocItem({ title: "全部单词", zh: `${all} 个词，不分主题，打乱顺序`, badge: String(vPracticeCount("all")), badgeCls: allDone === all ? "" : "zero",
    current: vTheme === "all", onClick: () => { vTheme = "all"; vSess = null; vToc(); vList(); afterPick(); } }));
  const weak = vThemeWords("weak").length;
  ul0.append(tocItem({ title: "生词本", zh: "答错过、还没练熟的词", badge: String(vPracticeCount("weak")), badgeCls: weak ? "bad" : "zero",
    current: vTheme === "weak", disabled: !weak, onClick: () => { vTheme = "weak"; vSess = null; vToc(); vList(); afterPick(); } }));
  // 闯关和巴黎塔尖在“游戏”模块里
