  ATTEMPT_TAGS.forEach(t=>{const b=el("button","chip");b.type="button";b.setAttribute("aria-pressed",String(vAttempts.includes(t)));b.append(document.createTextNode(t),el("small",null,String(vPracticeCount(vTheme,tagToggle(vAttempts,t)))));b.addEventListener("click",()=>{vAttempts=tagToggle(vAttempts,t);vToc();if(stage.querySelector(".v-table")||stage.querySelector(".empty"))vList();});chips.append(b);});
  toc.append(group);
