    const mk = (label, pressed, n, onClick) => { const b = el("button", "chip"); b.type = "button"; b.setAttribute("aria-pressed", String(pressed)); b.append(document.createTextNode(label), el("small", null, String(n))); b.addEventListener("click", onClick); cs.append(b); return b; };
