  const posItems = V_POS_GROUPS.filter(([k]) => V_WORDS.some(w => vPosGroup(w) === k)).map(([k, label]) => [k, label]);
  toc.append(chipGroup("词性", "vPosChips", posItems, vPosSel, v => { vPosSel = v; }, v => vPracticeCount(vTheme, vAttempts, vKinds, v)));
  toc.append(el("p","sub","目录数字表示选择该项后可检索的总题数；同一类里多选任一满足即可，不同类之间要同时满足。作答状态按每个词的每种题型分别判断，从下一组生效。"));
  toc.append(el("div", "toc-sec", "按主题（可选）"));
  const ul = el("ul");
