  if (vTheme === "spire") { spHome(); return; }
  stage.innerHTML = "";
  const card = el("section", "card");
  const words = vLvNo()>=0 ? vThemeWords(vTheme) : vPracticeWords(vTheme);
  const title = vTitle();
  const isLv = vLvNo() >= 0;
  const tags = el("div", "tagrow");
  tags.append(el("span", "tag", "背单词 · " + title), el("span", "tag plain", `${words.length} 个词`));
  card.append(tags);
  if (!words.length) { card.append(el("p", "empty", "当前筛选下没有可练习的词汇题，请调整词条类型、词性、作答状态或题型。")); stage.append(card); return; }
