const spDiffSel = () => { try { const v = localStorage.getItem("fq-spire-diff"); return v == null ? spUnlocked() : Number(v); } catch (e) { return 0; } };
const spAllKeys = () => SP_KEYS.every(([k]) => spKeys()[k]);
