  const svgNS = "http://www.w3.org/2000/svg", lines = document.createElementNS(svgNS, "svg");
  lines.setAttribute("class", "sp-lines"); lines.setAttribute("viewBox", `0 0 400 ${top + NR * H + 20}`); lines.setAttribute("preserveAspectRatio", "none");
  const X = (c, rr) => (((r.map[rr] && r.map[rr][c] && r.map[rr][c].x != null) ? r.map[rr][c].x : c) + .5) * 100, Y = rr => top + (NR - 1 - rr) * H + H / 2;
