    b.style.left = (X(c, rr) / 4) + "%"; b.style.top = Y(rr) + "px";
    b.append(spIcon("node", n.t));
    if (n.fire) { b.classList.add("fire"); const f = el("span", "sp-fire"); f.innerHTML = SP_ART.fire; b.append(f); }
    const done = r.path && r.path.some(p => p[0] === rr && p[1] === c);
    const open = rr === r.row + 1 && can.includes(c);
    if (done) b.classList.add("done");
