  { const s = el("span", "sp-legend-fire"); const f = el("span", "sp-ico"); f.innerHTML = SP_ART.fire; s.append(f, document.createTextNode("带火精英（绿钥匙）")); legend.append(s); }
  card.append(legend);
  // 钥匙进度
