    const seen=new Set();
    s.history=d.history.filter(e=>e && e.kind==='pomodoro' && typeof e.id==='string' && !seen.has(e.id) && seen.add(e.id) && ['complete','aborted'].includes(e.result) && Number.isFinite(e.at) && e.at>0 && Number.isFinite(e.ms) && e.ms>=0 && e.ms<=90*60000).map(e=>({id:e.id,kind:'pomodoro',result:e.result,at:e.at,ms:e.ms}));
