let pomoScope=null,pomoState=null,pomoError='',pomoBusy=false,pomoStarted=false,pomoRenderKey='',pomoContext=null,pomoLastClock=null,pomoLastAnnounce='';
const pomoKey = scope => 'fq-pomodoro:'+scope;
