// First-party, account-scoped visible-page duration. Never records input, URLs or audio.
const USAGE_PREFIX='fq-usage-outbox:', USAGE_MAX_AGE=7*86400000;
let usageUid='',usageLast=Date.now(),usageVisible=false,usageBusy=false,usageTicks=0;
const usagePending=new Map(),usagePreferences=new Map();
const usageAccount=()=>SYNC_ON?syncAuth()?.uid||'':'';
function usageEnabled(uid=usageAccount()){if(!uid)return false;if(usagePreferences.has(uid))return usagePreferences.get(uid);try{return localStorage.getItem('fq-usage-enabled:'+uid)!=='0';}catch(e){return true;}}
function usageMerge(map,minute,mask){try{const n=BigInt(mask);if(n>0n&&n<(1n<<60n))map.set(minute,(map.get(minute)||0n)|n);}catch(e){}}
function usageMark(map,start,end){
 if(!Number.isFinite(start)||!Number.isFinite(end)||end<=start)return;
 // A delayed/suspended timer is not evidence that the entire gap was viewed.
 start=Math.max(start,end-15000);
 for(let second=Math.floor(start/1000);second<Math.floor(end/1000);second++){
  const minute=new Date(Math.floor(second/60)*60000).toISOString();
  usageMerge(map,minute,1n<<BigInt(second%60));
 }
}
function usageCollect(now=Date.now()){
 if(usageUid&&usageVisible)usageMark(usagePending,usageLast,now);
 usageLast=now;
}
function usageRows(map){return [...map].sort(([a],[b])=>a.localeCompare(b)).map(([minute,mask])=>({minute,mask:String(mask)}));}
function usagePersist(){
 if(!usageUid||!usagePending.size)return;
 try{
  const key=USAGE_PREFIX+usageUid+':'+crypto.randomUUID();
  localStorage.setItem(key,JSON.stringify({at:Date.now(),minutes:usageRows(usagePending)}));usagePending.clear();
 }catch(e){} // Storage failure keeps the unsent seconds in memory.
}
function usageOutbox(uid){
 const found=[],prefix=USAGE_PREFIX+uid+':';
 try{
  const keys=Array.from({length:localStorage.length},(_,i)=>localStorage.key(i)).filter(k=>k?.startsWith(prefix));
  for(const key of keys){
   let data;try{data=JSON.parse(localStorage.getItem(key));}catch(e){}
   if(!data||!Number.isFinite(data.at)||data.at<Date.now()-USAGE_MAX_AGE||!Array.isArray(data.minutes)){localStorage.removeItem(key);continue;}
   found.push({key,...data});
  }
  found.sort((a,b)=>a.at-b.at);
  // Bound only this feature's retry cache. Never touch answers, coins or login data.
  while(found.length>4000)localStorage.removeItem(found.shift().key);
 }catch(e){}
 return found;
}
async function usageFlush(){
 if(usageBusy||!usageUid||usageAccount()!==usageUid||navigator.onLine===false)return;
 const uid=usageUid;usagePersist();const batches=usageOutbox(uid).slice(0,50),snapshot=new Map(usagePending),merged=new Map(snapshot);
 for(const b of batches)for(const row of b.minutes){const t=Date.parse(row.minute);if(Number.isFinite(t)&&t>=Date.now()-USAGE_MAX_AGE+60000&&t<=Date.now())usageMerge(merged,new Date(Math.floor(t/60000)*60000).toISOString(),row.mask);}
 const rows=usageRows(merged);if(!rows.length){for(const b of batches)try{localStorage.removeItem(b.key);}catch(e){}return;}
 usageBusy=true;
 try{
  // Outbox chunks are immutable; concurrent tabs may safely retry the same seconds.
  for(let i=0;i<rows.length;i+=120){
   const ac=new AbortController(),timer=setTimeout(()=>ac.abort(),12000);
   try{await syncFetch('/rest/v1/rpc/record_visible_usage',{method:'POST',body:JSON.stringify({p_minutes:rows.slice(i,i+120)}),signal:ac.signal,keepalive:true},true,uid);}
   finally{clearTimeout(timer);}
  }
  for(const b of batches)try{localStorage.removeItem(b.key);}catch(e){}
  if(usageUid===uid)for(const [minute,mask]of snapshot){const rest=(usagePending.get(minute)||0n)&~mask;if(rest)usagePending.set(minute,rest);else usagePending.delete(minute);}
 }catch(e){} // Best effort. The next heartbeat/visit retries without duplicating time.
 finally{usageBusy=false;}
}
function usageAccountChanged(){
 usageCollect();usagePersist();usagePending.clear();usageUid=usageAccount();usageLast=Date.now();usageVisible=!!usageUid&&usageEnabled(usageUid)&&document.visibilityState==='visible';void usageFlush();
}
function usageVisibility(){usageCollect();usageVisible=!!usageUid&&usageEnabled(usageUid)&&document.visibilityState==='visible';usagePersist();void usageFlush();}
function usageSetEnabled(enabled){
 const uid=usageAccount();if(!uid)return;usageCollect();usagePersist();
 usagePreferences.set(uid,enabled);try{localStorage.setItem('fq-usage-enabled:'+uid,enabled?'1':'0');}catch(e){}
 usageVisible=enabled&&document.visibilityState==='visible';usageLast=Date.now();void usageFlush();
}
function usageInit(){
 if(!SYNC_ON)return;usageAccountChanged();
 setInterval(()=>{if(usageAccount()!==usageUid){usageAccountChanged();return;}usageCollect();usageVisible=!!usageUid&&usageEnabled(usageUid)&&document.visibilityState==='visible';if(++usageTicks%6===0)void usageFlush();},5000);
 document.addEventListener('visibilitychange',usageVisibility);
 addEventListener('pagehide',()=>{usageCollect();usageVisible=false;usagePersist();void usageFlush();});
 addEventListener('pageshow',()=>{usageLast=Date.now();usageVisible=!!usageUid&&usageEnabled(usageUid)&&document.visibilityState==='visible';void usageFlush();});
 addEventListener('online',()=>void usageFlush());
 addEventListener('storage',e=>{if(e.key==='fq-usage-enabled:'+usageUid){usagePreferences.delete(usageUid);usageVisibility();}});
}
queueMicrotask(usageInit);

