 for(const days of [7,30]){const button=fbButton(usageText('最近 '+days+' 天','Last '+days+' days',days+' derniers jours'),'btn ghost');button.dataset.days=days;button.addEventListener('click',()=>{if(busy)return;const range=usageRecentRange(days);from.value=range.from;to.value=range.to;page=0;void load();});presets.push([days,button]);quick.append(button);}
